            )}
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700"><SectionTitle><span className="text-[11px] font-black text-gray-400 mr-1">01.</span> Dados do solicitante</SectionTitle><div className="grid grid-cols-1 md:grid-cols-12 gap-6"><div className="md:col-span-4"><FormLabel>Solicitante</FormLabel><div className="flex items-center gap-3 p-2 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100"><div className="w-7 h-7 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-black text-[10px]">{solicitante.substring(0, 1).toUpperCase()}</div><span className="text-xs font-black text-gray-700 dark:text-gray-200">{solicitante}</span></div></div><div className="md:col-span-4"><FormLabel>Setor / obra</FormLabel><input className="w-full rounded-lg border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-2.5 text-xs font-bold text-gray-700 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500/20" value={setor} onChange={(e:any) => setSetor(e.target.value)} disabled={isReadOnly} /></div><div className="md:col-span-4"><FormLabel>Período</FormLabel><div className="flex items-center gap-2"><input className="w-full rounded-lg border-gray-200 bg-white dark:bg-gray-800 p-2.5 text-xs font-bold" type="date" value={periodStart} onChange={(e:any) => setPeriodStart(e.target.value)} disabled={isReadOnly} />- <input className="w-full rounded-lg border-gray-200 bg-white dark:bg-gray-800 p-2.5 text-xs font-bold" type="date" value={periodEnd} onChange={(e:any) => setPeriodEnd(e.target.value)} disabled={isReadOnly} /></div></div></div></div>
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden"><div className="p-5 border-b flex justify-between items-center"><h3 className="text-xs font-black text-gray-800 dark:text-white flex items-center gap-2"><TableIcon className="w-4 h-4 text-indigo-600" /> Detalhamento de gastos</h3><div className="px-3 py-1 bg-indigo-50 text-indigo-700 rounded-lg text-[9px] font-black border">Custo km: R$ {valorPorKm.toFixed(2)}</div></div><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-gray-50 dark:bg-gray-800 text-[9px] font-bold text-gray-400"><tr><th className="px-6 py-4">Data / finalidade</th><th className="px-4 py-4 text-center">Km</th><th className="px-4 py-4 text-center">Pedágio</th><th className="px-4 py-4 text-center">Alim.</th><th className="px-4 py-4 text-center">Comp.</th><th className="px-4 py-4 text-center">Outros</th><th className="px-6 py-4 text-right">Subtotal</th>{!isReadOnly && <th className="px-4 w-10"></th>}</tr></thead><tbody className="divide-y">{items.map((item) => (<tr key={item.id} className="hover:bg-indigo-50/10 group"><td className="px-6 py-3 min-w-[280px]"><div className="flex gap-2 items-center"><input type="date" value={item.date} onChange={e => setItems(p=>p.map(x=>x.id===item.id?{...x, date:e.target.value}:x))} disabled={isReadOnly} className="bg-transparent text-[11px] font-bold outline-none text-indigo-600" /><input type="text" value={item.description} onChange={e => setItems(p=>p.map(x=>x.id===item.id?{...x, description:e.target.value}:x))} disabled={isReadOnly} className="bg-transparent text-[11px] font-bold text-gray-700 dark:text-gray-200 outline-none flex-1" /></div></td><td className="px-2 py-3"><input type="number" value={item.km || ''} onChange={e => setItems(p=>p.map(x=>x.id===item.id?{...x, km:parseFloat(e.target.value)||0}:x))} disabled={isReadOnly} className="w-full text-center bg-transparent text-[11px] font-black text-indigo-600 outline-none" /></td>{['toll', 'food', 'components', 'others'].map(field => (<td key={field} className="px-2 py-3"><input type="number" value={(item as any)[field] || ''} onChange={e => setItems(p=>p.map(x=>x.id===item.id?{...x, [field]:parseFloat(e.target.value)||0}:x))} disabled={isReadOnly} className="w-full text-right bg-transparent text-[11px] font-bold outline-none" placeholder="0,00" /></td>))}<td className="px-6 py-3 text-right font-black text-gray-900 dark:text-white">{formatCurrency(Math.ceil(((item.km || 0)*valorPorKm)*100)/100 + (item.toll || 0) + (item.food || 0) + (item.components || 0) + (item.others || 0))}</td>{!isReadOnly && (<td className="px-4 py-3"><button onClick={() => setItems(p => p.filter(i => i.id !== item.id))} className="opacity-0 group-hover:opacity-100 text-gray-300 hover:text-red-500"><TrashIcon className="w-4 h-4" /></button></td>)}</tr>))}</tbody></table></div>{!isReadOnly && (<div className="p-4 bg-gray-50/30"><button onClick={() => setItems([...items, { id: Date.now().toString(), date: '', description: '', km: 0, toll: 0, food: 0, components: 0, others: 0 }])} className="w-full flex items-center justify-center gap-2 py-3 border-2 border-dashed border-gray-100 text-gray-400 hover:text-indigo-600 rounded-xl font-black text-[10px]"><PlusIcon className="w-4 h-4" /> Adicionar linha</button></div>)}</div>
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6"><div className="lg:col-span-7 bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-100 dark:border-gray-700"><SectionTitle color="bg-amber-500"><span className="text-[11px] font-black text-gray-400 mr-1">02.</span> Comprovantes</SectionTitle><div className="grid grid-cols-4 gap-3">{attachments.map((file, idx) => {
              const isPdf = file.name.toLowerCase().endsWith('.pdf') || file.data.startsWith('data:application/pdf');
              return (
              <div key={idx} className="group relative aspect-square bg-gray-50 dark:bg-gray-900 rounded-xl border overflow-hidden shadow-sm flex items-center justify-center">
                  {isPdf ? <DocumentReportIcon className="w-8 h-8 text-red-500" /> : <img src={file.data} className="w-full h-full object-cover" alt="" />}
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 z-10">
                      <button onClick={() => handleViewFile(file)} className="p-1.5 bg-white text-gray-900 rounded-full shadow-lg hover:bg-indigo-50" title="Visualizar"><EyeIcon className="w-4 h-4" /></button>
                      <button onClick={() => handleDownloadFile(file)} className="p-1.5 bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700" title="Baixar"><ArrowDownIcon className="w-4 h-4" /></button>
                  </div>
              </div>
          )})} {!isReadOnly && <button onClick={() => attachmentInputRef.current?.click()} className="aspect-square flex flex-col items-center justify-center border-2 border-dashed border-indigo-100 rounded-xl text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 transition-all"><UploadIcon className="w-6 h-6 mb-1" /><span className="text-[9px] font-black tracking-tighter">Anexar</span></button>}</div><input type="file" multiple className="hidden" ref={attachmentInputRef} accept="image/*,application/pdf" onChange={e => { const files = e.target.files; if (!files) return; (Array.from(files) as File[]).forEach(file => { const reader = new FileReader(); reader.onload = ev => { if (typeof ev.target?.result === 'string') setAttachments(p => [...p, { name: file.name, data: ev.target!.result as string }]); }; reader.readAsDataURL(file); }); e.target.value = ''; }} /></div><div className="lg:col-span-5"><div className="bg-indigo-600 rounded-xl p-6 text-white shadow-xl shadow-indigo-100 dark:shadow-none sticky top-6"><h3 className="text-sm font-black mb-6 flex items-center gap-2 opacity-80"><DollarIcon className="w-4 h-4" /> Resumo financeiro</h3><div className="space-y-3.5 mb-6">{[{ label: "Total em km", val: (items || []).reduce((acc, item) => acc + (Math.ceil(((item.km || 0) * valorPorKm) * 100) / 100), 0) }, { label: "Total em pedágios", val: (items || []).reduce((acc, item) => acc + (item.toll || 0), 0) }, { label: "Total alimentação", val: (items || []).reduce((acc, item) => acc + (item.food || 0), 0) }, { label: "Compra de componentes", val: (items || []).reduce((acc, item) => acc + (item.components || 0), 0) }, { label: "Outros custos", val: (items || []).reduce((acc, item) => acc + (item.others || 0), 0) }].map(row => (<div key={row.label} className="flex justify-between items-center text-[11px] font-medium border-b border-white/10 pb-2.5 last:border-0 last:pb-0"><span className="opacity-70">{row.label}</span><span className="font-black">{formatCurrency(row.val)}</span></div>))}</div><div className="pt-5 border-t border-white/20"><p className="text-[10px] font-black opacity-60 mb-1">Valor total a receber</p><p className="text-3xl font-black leading-none">{formatCurrency((items || []).reduce((acc, item) => acc + (Math.ceil(((item.km || 0) * valorPorKm) * 100) / 100) + (item.toll || 0) + (item.food || 0) + (item.components || 0) + (item.others || 0), 0))}</p></div></div></div></div>
      </div>
    );
  };

  return (
    <>
        {renderContent()}
        {isConfirmEfetivarHistoricoModal && (
            <Modal title="Confirmar efetivação" onClose={() => setIsConfirmEfetivarHistoricoModal(false)}>
                <div className="text-center p-4 space-y-4">
                    <CheckCircleIcon className="w-12 h-12 text-green-500 mx-auto" />
                    <h3 className="text-sm font-bold">Deseja efetivar o reembolso?</h3>
                    <p className="text-[10px] text-gray-500">O status mudará para 'Transferido' e a edição será bloqueada.</p>
                    <div className="flex gap-3 mt-4">
                        <button onClick={() => setIsConfirmEfetivarHistoricoModal(false)} className="flex-1 py-2 bg-gray-100 rounded-lg text-xs font-bold">Não</button>
                        <button onClick={handleEfetivarHistorico} disabled={isLoading} className="flex-1 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold shadow-lg">Sim, efetivar</button>
                    </div>
                </div>
            </Modal>
        )}
        {isConfirmEfetivarStatusModal && (
            <Modal title="Aprovar para pagamento" onClose={() => setIsConfirmEfetivarStatusModal(false)}>
                <div className="text-center p-4 space-y-4">
                    <DollarIcon className="w-12 h-12 text-indigo-600 mx-auto" />
                    <h3 className="text-sm font-bold">Deseja aprovar este reembolso?</h3>
                    <p className="text-[10px] text-gray-500">{reportInAction?.isInstallmentWash ? "Esta ação autoriza o pagamento e marca os itens vinculados como 'Liberados' no financeiro." : "Esta ação criará um lançamento no financeiro para pagamento em 7 dias."}</p>
                    <div className="flex gap-3 mt-4">
                        <button onClick={() => setIsConfirmEfetivarStatusModal(false)} className="flex-1 py-2 bg-gray-100 rounded-lg text-xs font-bold">Não</button>
                        <button onClick={handleEfetivarStatus} disabled={isLoading} className="flex-1 py-2 bg-green-600 text-white rounded-lg text-xs font-bold shadow-lg">Sim, aprovar</button>
                    </div>
                </div>
            </Modal>
        )}
        {isCancelModalOpen && (
            <Modal title="Cancelar reembolso" onClose={() => setIsCancelModalOpen(false)}>
                <div className="space-y-4">
                    <div><FormLabel>Motivo do cancelamento *</FormLabel><textarea value={cancelReason} onChange={(e) => setCancelReason(e.target.value)} className="w-full rounded-lg border-gray-200 bg-gray-50 p-3 text-xs font-bold outline-none focus:ring-2 focus:ring-red-500/20" placeholder="Motivo..." rows={4} /></div>
                    <div className="flex gap-3"><button onClick={() => setIsCancelModalOpen(false)} className="flex-1 py-2 bg-gray-100 rounded-lg text-xs font-bold">Voltar</button><button onClick={handleCancelarStatus} disabled={isLoading || !cancelReason.trim()} className="flex-1 py-2 bg-red-600 text-white rounded-xl font-bold text-xs shadow-lg">Confirmar</button></div>
                </div>
            </Modal>
        )}
        {isSuccessModalOpen && (
            <Modal title="" onClose={handleSuccessModalClose}>
                <div className="text-center py-6 space-y-4">
                    <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto animate-bounce"><CheckCircleIcon className="w-10 h-10" /></div>
                    <h3 className="text-lg font-black text-gray-900 tracking-tight">Concluído!</h3>
                    <p className="text-xs font-bold text-gray-500 px-4 leading-relaxed">{modalMessage}</p>
                    <button onClick={handleSuccessModalClose} className="w-full mt-4 py-3 bg-gray-900 text-white rounded-xl font-bold text-xs">Ok, entendi</button>
                </div>
            </Modal>
        )}
        {hdPhoto && (
            <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setHdPhoto(null)}>
                <div className="relative max-w-5xl w-full h-full flex flex-col items-center justify-center gap-4">
                    <button className="absolute top-0 right-0 p-3 text-white hover:text-indigo-400 z-[110]" onClick={(e) => { e.stopPropagation(); setHdPhoto(null); }}><XCircleIcon className="w-10 h-10" /></button>
                    <div className="flex-1 w-full flex items-center justify-center overflow-hidden"><img src={hdPhoto} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoom-in" alt="" onClick={(e) => e.stopPropagation()} /></div>
                </div>
            </div>
        )}
    </>
  );
};

export default RelatoriosPage;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardPage from './pages/DashboardPage';
import WelcomePage from './pages/WelcomePage';
import OrcamentoPage from './pages/OrcamentoPage';
import FinanceiroPage from './pages/FinanceiroPage';
import RelatoriosPage from './pages/RelatoriosPage';
import NovoOrcamentoPage from './pages/NovoOrcamentoPage';
import ResumoVendasPage from './pages/ResumoVendasPage';
import EstoquePage from './pages/EstoquePage';
import CheckListPage from './pages/CheckListPage';
import HomologacaoPage from './pages/HomologacaoPage';
import UsuariosPage from './pages/UsuariosPage';
import LoginPage from './pages/LoginPage';
import InstalacoesPage from './pages/InstalacoesPage';
import InstalacoesCadastroPage from './pages/InstalacoesCadastroPage';
import LavagemPage from './pages/LavagemPage';
import InstalacaoLavagemPage from './pages/InstalacaoLavagemPage';
import { LockClosedIcon, ExclamationTriangleIcon } from './assets/icons';
import type { Page, SavedOrcamento, ExpenseReport, User, UserProfile } from './types';
import { dataService } from './services/dataService';
import { authService } from './services/authService';
import { MOCK_PROFILES } from './constants';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('DASHBOARD');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [editingOrcamento, setEditingOrcamento] = useState<SavedOrcamento | null>(null);
  const [editingReport, setEditingReport] = useState<ExpenseReport | null>(null);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [userPermissions, setUserPermissions] = useState<string[]>([]);
  const [hasGlobalView, setHasGlobalView] = useState(false);
  const [isUserInitialized, setIsUserInitialized] = useState(false);
  const [companyLogo, setCompanyLogo] = useState<string | null>(null);

  const ADMIN_PROFILE_ID = '001';

  const fetchCompanyLogo = async () => {
    try {
      const configs = await dataService.getAll<any>('system_configs', undefined, true);
      const logoConfig = configs.find(c => c.id === 'company_logo');
      if (logoConfig && logoConfig.value) {
        setCompanyLogo(logoConfig.value);
      }
    } catch (e) {
      console.warn("Erro ao carregar logo da empresa:", e);
    }
  };

  useEffect(() => {
    if (currentUser?.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [currentUser?.darkMode]);

  const fetchPermissions = async (profileId: string) => {
    try {
      const profiles = await dataService.getAll<UserProfile>('system_profiles', undefined, true);
      let profile = profiles.find(p => String(p.id) === String(profileId));

      if (!profile) profile = MOCK_PROFILES.find(p => String(p.id) === String(profileId));

      if (profile) {
          setUserPermissions(profile.permissions || []);
          setHasGlobalView(!!profile.hasGlobalView);
      } else if (profileId === ADMIN_PROFILE_ID) {
          setUserPermissions(['ALL']);
          setHasGlobalView(true);
      } else {
          setUserPermissions([]);
          setHasGlobalView(false);
      }
    } catch (e) {
      console.warn("Utilizando permissões de fallback devido a erro de conexão.");
      if (profileId === ADMIN_PROFILE_ID) {
          setUserPermissions(['ALL']);
          setHasGlobalView(true);
      } else {
          setUserPermissions([]);
          setHasGlobalView(false);
      }
    }
  };

  useEffect(() => {
    const session = authService.getSession();
    if (session) {
        setCurrentUser(session);
        fetchPermissions(session.profileId);
    }
    fetchCompanyLogo();
    setIsUserInitialized(true);
  }, []);

  const handleLoginSuccess = (user: User) => {
      setCurrentUser(user);
      fetchPermissions(user.profileId);
  };

  const handleLogout = () => {
      authService.logout();
      setCurrentUser(null);
      setUserPermissions([]);
      setHasGlobalView(false);
      setCurrentPage('DASHBOARD');
  };

  const handleSetCurrentPage = (page: Page) => {
    if (page !== 'NOVO_ORCAMENTO') setEditingOrcamento(null);
    if (page !== 'RELATORIOS_NOVO' && page !== 'INSTALACAO_LAVAGEM_SOLIC') setEditingReport(null);
    setCurrentPage(page);
  }

  const handleEditOrcamento = (orcamento: SavedOrcamento) => {
    setEditingOrcamento(orcamento);
    setCurrentPage('NOVO_ORCAMENTO');
  };

  const handleEditReport = (report: ExpenseReport) => {
      setEditingReport(report);
      if (report.isInstallmentWash || (report.id && report.id.startsWith('tech-'))) {
          setCurrentPage('INSTALACAO_LAVAGEM_SOLIC');
      } else {
          setCurrentPage('RELATORIOS_NOVO');
      }
  }

  const handleSaveReport = () => {
      setEditingReport(null);
      setCurrentPage('RELATORIOS_HISTORICO');
  }

  const hasPermission = (page: Page) => {
      if (userPermissions.includes('ALL')) return true; 
      return userPermissions.includes(page);
  };

  const renderPage = () => {
    if (!currentUser) return null;

    if (!currentUser.active) {
        return (
            <div className="flex flex-col items-center justify-center h-full space-y-6 text-center px-4">
                <div className="p-6 bg-red-100 rounded-full text-red-600 shadow-xl">
                    <LockClosedIcon className="w-20 h-20" />
                </div>
                <h2 className="text-3xl font-black text-gray-900 dark:text-white">Acesso bloqueado</h2>
                <button onClick={handleLogout} className="text-xs text-indigo-600 font-bold hover:underline">Sair</button>
            </div>
        );
    }

    if (currentPage === 'DASHBOARD' && !hasPermission('DASHBOARD')) {
        return <WelcomePage currentUser={currentUser} userPermissions={userPermissions} onNavigate={handleSetCurrentPage} />;
    }

    if (!hasPermission(currentPage)) {
        return (
            <div className="flex flex-col items-center justify-center h-full space-y-4 text-center">
                <ExclamationTriangleIcon className="w-16 h-16 text-amber-500" />
                <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Acesso restrito</h2>
                <button onClick={() => setCurrentPage('DASHBOARD')} className="mt-4 px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold">Voltar</button>
            </div>
        );
    }

    switch (currentPage) {
      case 'DASHBOARD': return <DashboardPage />;
      case 'ORCAMENTO': return <OrcamentoPage setCurrentPage={handleSetCurrentPage} onEdit={handleEditOrcamento} currentUser={currentUser} hasGlobalView={hasGlobalView} />;
      case 'NOVO_ORCAMENTO': return <NovoOrcamentoPage setCurrentPage={handleSetCurrentPage} orcamentoToEdit={editingOrcamento} clearEditingOrcamento={() => setEditingOrcamento(null)} currentUser={currentUser} />;
      /* Fix: ResumoVendasPage does not accept hasGlobalView prop */
      case 'RESUMO_VENDAS': return <ResumoVendasPage currentUser={currentUser} />;
      case 'FINANCEIRO_VISAO_GERAL': return <FinanceiroPage view="dashboard" currentUser={currentUser} hasGlobalView={hasGlobalView} />;
      case 'FINANCEIRO_DRE': return <FinanceiroPage view="dre" currentUser={currentUser} hasGlobalView={hasGlobalView} />;
      case 'FINANCEIRO_CATEGORIAS': return <FinanceiroPage view="categorias" currentUser={currentUser} />;
      case 'FINANCEIRO_BANCOS': return <FinanceiroPage view="bancos" currentUser={currentUser} hasGlobalView={hasGlobalView} />;
      case 'ESTOQUE_VISAO_GERAL': return <EstoquePage view="visao_geral" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'ESTOQUE_NOVO_PRODUTO': return <EstoquePage view="cadastro" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'ESTOQUE_COMPRAS': return <EstoquePage view="compras" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'CHECKLIST_CHECKIN': return <CheckListPage view="checkin" currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'CHECKLIST_CHECKOUT': return <CheckListPage view="checkout" currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'CHECKLIST_MANUTENCAO': return <CheckListPage view="manutencao" currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'CHECKLIST_HOMOLOGACAO': return <HomologacaoPage currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'RELATORIOS_VISAO_GERAL': return <RelatoriosPage view="analise" currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'RELATORIOS_NOVO': return <RelatoriosPage view="reembolso" reportToEdit={editingReport} onSave={handleSaveReport} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'RELATORIOS_STATUS': return <RelatoriosPage view="status" onEditReport={handleEditReport} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      case 'RELATORIOS_HISTORICO': return <RelatoriosPage view="historico" onEditReport={handleEditReport} currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} />;
      /* Fix: RelatoriosPage requires userPermissions prop even in config view */
      case 'RELATORIOS_CONFIG': return <RelatoriosPage view="config" currentUser={currentUser} userPermissions={userPermissions} hasGlobalView={hasGlobalView} onLogoUpdated={fetchCompanyLogo} />;
      case 'INSTALACAO_LAVAGEM_SOLIC': return <InstalacaoLavagemPage currentUser={currentUser} reportToEdit={editingReport} onSave={handleSaveReport} hasGlobalView={hasGlobalView} />;
      case 'INSTALACOES_CALENDARIO': return <InstalacoesPage currentUser={currentUser} hasGlobalView={hasGlobalView} />;
      case 'INSTALACOES_CADASTRO': return <InstalacoesCadastroPage currentUser={currentUser} />;
      /* Fix: LavagemPage does not accept hasGlobalView prop */
      case 'INSTALACOES_LAVAGEM': return <LavagemPage currentUser={currentUser} />;
      case 'USUARIOS_GESTAO': return <UsuariosPage view="gestao" currentUser={currentUser} />;
      case 'USUARIOS_PERFIL': return <UsuariosPage view="perfil" currentUser={currentUser} />;
      default: return <DashboardPage />;
    }
  };

  if (!isUserInitialized) return null;
  if (!currentUser) return <LoginPage onLoginSuccess={handleLoginSuccess} companyLogo={companyLogo} />;

  return (
    <div className="flex h-screen bg-gray-100 dark:bg-gray-900 text-gray-800 dark:text-gray-200 transition-colors duration-300">
      <Sidebar currentPage={currentPage} setCurrentPage={handleSetCurrentPage} isSidebarOpen={isSidebarOpen} setSidebarOpen={setSidebarOpen} currentUser={currentUser} userPermissions={userPermissions} onLogout={handleLogout} companyLogo={companyLogo} />
      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
        <Header title="Sistema Orner" onMenuClick={() => setSidebarOpen(!isSidebarOpen)} />
        <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 sm:p-6 md:p-8">
          {renderPage()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
    CubeIcon, TrashIcon, PlusIcon, 
    ExclamationTriangleIcon, DollarIcon, EditIcon, PhotographIcon, XCircleIcon,
    ArrowUpIcon, ArrowDownIcon, FilterIcon, CalendarIcon, ClipboardListIcon, ShoppingCartIcon, LinkIcon,
    EyeIcon, CheckCircleIcon, TableIcon, UploadIcon, DocumentReportIcon, ChartPieIcon, ClockIcon, TruckIcon, UsersIcon, SearchIcon, ChevronDownIcon
} from '../assets/icons';
import type { StockItem, EstoquePageProps, PurchaseRequest, StockMovement, ChecklistEntry, PriceHistoryEntry, PurchaseRequestStatus, SavedOrcamento } from '../types';
import { dataService } from '../services/dataService';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';

const UNITS = ["un", "mt", "kg", "cx", "par", "kit", "pç", "m²", "lt"];
const ADMIN_PROFILE_ID = '001';

// Componente para labels de formulário padronizado
const FormLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="block text-[12px] font-bold text-gray-500 mb-1 tracking-tight">{children}</label>
);

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage, currentUser, userPermissions }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [requests, setRequests] = useState<PurchaseRequest[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [checkins, setCheckins] = useState<ChecklistEntry[]>([]);
    const [approvedClients, setApprovedClients] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    const [activeTab, setActiveTab] = useState<'inventario' | 'historico'>('inventario');
    const [purchaseStatusFilter, setPurchaseStatusFilter] = useState<'Todos' | PurchaseRequestStatus>('Todos');

    // Filtros para o Histórico de Movimentação
    const [historyItemId, setHistoryItemId] = useState<string>('Todos');
    const [historySearchTerm, setHistorySearchTerm] = useState('');
    const [showHistorySuggestions, setShowHistorySuggestions] = useState(false);
    const historySuggestionRef = useRef<HTMLDivElement>(null);

    const [historyStart, setHistoryStart] = useState<string>('');
    const [historyEnd, setHistoryEnd] = useState<string>('');

    const [isRequestModalOpen, setIsRequestModalOpen] = useState(false);
    const [requestToEdit, setRequestToEdit] = useState<PurchaseRequest | null>(null);
    const [isManualItem, setIsManualItem] = useState(false);

    // States for status transition confirmation
    const [isConfirmStatusModalOpen, setIsConfirmStatusModalOpen] = useState(false);
    const [confirmRequest, setConfirmRequest] = useState<PurchaseRequest | null>(null);
    const [nextStatus, setNextStatus] = useState<PurchaseRequestStatus | null>(null);

    // Estado para histórico de custos
    const [isPriceHistoryModalOpen, setIsPriceHistoryModalOpen] = useState(false);
    const [selectedItemForHistory, setSelectedItemForHistory] = useState<StockItem | null>(null);

    // Estado para detalhamento de reservas
    const [isReservationModalOpen, setIsReservationModalOpen] = useState(false);
    const [selectedItemForReservation, setSelectedItemForReservation] = useState<StockItem | null>(null);

    // Estado para cadastro de produtos
    const [isProductModalOpen, setIsProductModalOpen] = useState(false);
    const [productToEdit, setStockItemToEdit] = useState<StockItem | null>(null);
    const [productForm, setProductForm] = useState({
        name: '', ncm: '', quantity: 0, minQuantity: 1, unit: 'un', description: '', image: '', averagePrice: 0, isFixedInBudget: true
    });

    const [isNFModalOpen, setIsNFModalOpen] = useState(false);
    const [nfForm, setNfForm] = useState({
        invoiceNumber: '', invoiceKey: '', totalValue: 0, invoiceFile: '', invoiceFileName: ''
    });

    const [requestForm, setRequestForm] = useState({
        itemName: '', 
        quantity: 1, 
        unit: 'un', 
        priority: 'Média' as 'Baixa' | 'Média' | 'Alta', 
        clientName: '', 
        observation: '', 
        purchaseLink: '',
        purchaseType: 'Reposição' as 'Reposição' | 'Obra' | 'Avulso',
        requestDate: new Date().toISOString().split('T')[0]
    });

    const isAdmin = useMemo(() => String(currentUser.profileId) === ADMIN_PROFILE_ID || userPermissions.includes('ALL'), [currentUser, userPermissions]);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [loadedItems, loadedMovements, loadedRequests, loadedOrcamentos, loadedCheckins] = await Promise.all([
                dataService.getAll<StockItem>('stock_items', currentUser.id, true),
                dataService.getAll<StockMovement>('stock_movements', currentUser.id, true),
                view === 'compras' ? dataService.getAll<PurchaseRequest>('purchase_requests', currentUser.id, isAdmin) : Promise.resolve([]),
                dataService.getAll<SavedOrcamento>('orcamentos', currentUser.id, isAdmin),
                dataService.getAll<ChecklistEntry>('checklist_checkin', currentUser.id, isAdmin)
            ]);

            setItems(loadedItems.sort((a,b) => (a.name || '').localeCompare(b.name || '')));
            setMovements(loadedMovements.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
            setCheckins(loadedCheckins);

            if (view === 'compras') {
                setRequests(loadedRequests.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));

                const clients = loadedOrcamentos
                    .filter(orc => orc.status === 'Aprovado')
                    .map(orc => {
                        if (orc.variants?.length) {
                            const p = orc.variants.find(v => v.isPrincipal) || orc.variants[0];
                            return p.formState?.nomeCliente;
                        }
                        return orc.formState?.nomeCliente;
                    })
                    .filter(name => !!name);

                setApprovedClients(Array.from(new Set(clients)).sort());
            }
        } catch (error) { console.error("Erro:", error); } finally { setIsLoading(false); }
    };

    useEffect(() => { loadData(); }, [currentUser, view]);

    // Clique fora das sugestões do histórico
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (historySuggestionRef.current && !historySuggestionRef.current.contains(event.target as Node)) {
                setShowHistorySuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleUpdateStatus = async () => {
        if (!confirmRequest || !nextStatus) return;
        setIsSaving(true);
        try {
            const updated = { ...confirmRequest, status: nextStatus };
            await dataService.save('purchase_requests', updated);
            await loadData();
            setIsConfirmStatusModalOpen(false);
            setConfirmRequest(null);
            setNextStatus(null);
            setIsRequestModalOpen(false);
            setRequestToEdit(null);
        } catch (e) { 
            alert("Erro ao atualizar status"); 
        }
        finally { 
            setIsSaving(false); 
        }
    };

    const triggerStatusConfirmation = (request: PurchaseRequest, status: PurchaseRequestStatus) => {
        setConfirmRequest(request);
        setNextStatus(status);
        setIsConfirmStatusModalOpen(true);
    };

    const handleSaveRequest = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!requestForm.itemName.trim()) return;
        setIsSaving(true);
        try {
            const requestData: PurchaseRequest = {
                id: requestToEdit ? requestToEdit.id : String(Date.now()),
                owner_id: requestToEdit ? requestToEdit.owner_id : currentUser.id,
                itemName: requestForm.itemName,
                quantity: Number(requestForm.quantity),
                unit: requestForm.unit,
                requester: requestToEdit ? requestToEdit.requester : currentUser.name,
                date: requestForm.requestDate,
                priority: requestForm.priority,
                status: requestToEdit ? requestToEdit.status : 'Aberto',
                clientName: requestForm.purchaseType === 'Obra' ? requestForm.clientName : 'Estoque central',
                purchaseLink: requestForm.purchaseLink,
                purchaseType: requestForm.purchaseType, 
                observation: requestForm.observation
            };
            await dataService.save('purchase_requests', requestData);
            setIsRequestModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleNFFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const base64 = event.target?.result as string;
                setNfForm(prev => ({
                    ...prev,
                    invoiceFile: base64,
                    invoiceFileName: file.name
                }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleConfirmFinalization = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!requestToEdit) return;
        setIsSaving(true);
        try {
            const request = requestToEdit;
            const stockItem = items.find(i => i.name.toLowerCase() === request.itemName.toLowerCase());

            if (stockItem) {
                const newUnitCost = nfForm.totalValue / request.quantity;
                const currentQty = stockItem.quantity || 0;
                const currentAvgPrice = stockItem.averagePrice || 0;
                const newQtyTotal = currentQty + request.quantity;
                const weightedAveragePrice = ((currentQty * currentAvgPrice) + (request.quantity * newUnitCost)) / newQtyTotal;

                const historyEntry: PriceHistoryEntry = {
                    date: new Date().toISOString(), price: newUnitCost, invoiceNumber: nfForm.invoiceNumber
                };
                const updatedPriceHistory = [...(stockItem.priceHistory || []), historyEntry];

                await dataService.save('stock_items', {
                    ...stockItem,
                    quantity: newQtyTotal,
                    averagePrice: Math.round(weightedAveragePrice * 100) / 100,
                    priceHistory: updatedPriceHistory
                });

                await dataService.save('stock_movements', {
                    id: `mov-${Date.now()}`,
                    owner_id: currentUser.id,
                    itemId: String(stockItem.id),
                    quantity: request.quantity,
                    type: 'entrada',
                    date: new Date().toISOString(),
                    observation: `Entrada via nf ${nfForm.invoiceNumber}`
                });
            }

            await dataService.save('purchase_requests', { 
                ...request, 
                status: 'Concluído',
                invoiceFile: nfForm.invoiceFile || undefined,
                invoiceKey: nfForm.invoiceKey || undefined,
                observation: `${request.observation || ''}\n[Efetivado: nf ${nfForm.invoiceNumber}]`.trim()
            });

            setIsNFModalOpen(false);
            setRequestToEdit(null);
            await loadData();
            alert("Compra efetivada com sucesso! estoque atualizado.");
        } finally { setIsSaving(false); }
    };

    const handleSaveProduct = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!productForm.name.trim()) return;
        setIsSaving(true);
        try {
            const itemData: StockItem = {
                id: productToEdit ? productToEdit.id : `prod-${Date.now()}`,
                owner_id: productToEdit ? productToEdit.owner_id : currentUser.id,
                name: productForm.name,
                ncm: productForm.ncm,
                quantity: Number(productForm.quantity),
                reservedQuantity: productToEdit ? productToEdit.reservedQuantity : 0,
                minQuantity: productForm.minQuantity,
                unit: productForm.unit,
                description: productForm.description,
                image: productForm.image,
                averagePrice: productForm.averagePrice,
                isFixedInBudget: productForm.isFixedInBudget,
                priceHistory: productToEdit ? productToEdit.priceHistory : (Number(productForm.quantity) > 0 ? [{
                    date: new Date().toISOString(),
                    price: productForm.averagePrice,
                }] : [])
            };
            await dataService.save('stock_items', itemData);
            setIsProductModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleDeleteProduct = async (id: string | number) => {
        if (confirm("Deseja realmente excluir este produto?")) {
            await dataService.delete('stock_items', id);
            await loadData();
        }
    };

    const handleProductPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                setProductForm(prev => ({ ...prev, image: event.target?.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const formatCurrency = (value: number) => {
        if (isNaN(value)) return 'R$ 0,00';
        const rounded = Math.ceil(value * 100) / 100;
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
    };

    const getStatusInfo = (status: PurchaseRequestStatus) => {
        switch(status) {
            case 'Aberto': return { color: 'bg-gray-100 text-gray-700', icon: PlusIcon, label: 'Aberto' };
            case 'Aprovado': return { color: 'bg-blue-100 text-blue-700', icon: CheckCircleIcon, label: 'Aprovado' };
            case 'Comprado': return { color: 'bg-indigo-100 text-indigo-700', icon: ShoppingCartIcon, label: 'Comprado' };
            case 'Em trânsito': return { color: 'bg-purple-100 text-purple-700', icon: TruckIcon, label: 'Em trânsito' };
            case 'Concluído': return { color: 'bg-green-100 text-green-700', icon: CheckCircleIcon, label: 'Concluído' };
            case 'Cancelado': return { color: 'bg-red-100 text-red-700', icon: XCircleIcon, label: 'Cancelado' };
            default: return { color: 'bg-gray-100 text-gray-400', icon: PlusIcon, label: status };
        }
    };

    const filteredRequests = useMemo(() => {
        if (purchaseStatusFilter === 'Todos') return requests;
        return requests.filter(r => r.status === purchaseStatusFilter);
    }, [requests, purchaseStatusFilter]);

    const filteredMovements = useMemo(() => {
        return movements.filter(mov => {
            const matchesItem = historyItemId === 'Todos' || String(mov.itemId) === historyItemId;
            const movDate = mov.date.split('T')[0];
            const matchesStart = !historyStart || movDate >= historyStart;
            const matchesEnd = !historyEnd || movDate <= historyEnd;
            return matchesItem && matchesStart && matchesEnd;
        });
    }, [movements, historyItemId, historyStart, historyEnd]);

    const filteredItemsForHistory = useMemo(() => {
        if (!historySearchTerm) return items;
        return items.filter(i => i.name.toLowerCase().includes(historySearchTerm.toLowerCase()));
    }, [items, historySearchTerm]);

    const handleSelectHistoryItem = (item: StockItem | 'Todos') => {
        if (item === 'Todos') {
            setHistoryItemId('Todos');
            setHistorySearchTerm('');
        } else {
            setHistoryItemId(String(item.id));
            setHistorySearchTerm(item.name);
        }
        setShowHistorySuggestions(false);
    };

    const editableFieldClass = "w-full rounded-lg border-2 border-indigo-400 dark:border-indigo-600 bg-white dark:bg-gray-800 px-3 py-1.5 text-[13px] font-bold text-gray-800 dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-600 transition-all shadow-sm block";
    const labelSentenceClass = "block text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-0.5 ml-0.5";

    const handleManageRequest = (req: PurchaseRequest) => {
        setRequestToEdit(req);
        /* Fix: Cast req.purchaseType to the expected literal union to fix type assignment error */
        setRequestForm({
            itemName: req.itemName,
            quantity: req.quantity,
            unit: req.unit,
            priority: req.priority,
            clientName: req.clientName || '',
            observation: req.observation || '',
            purchaseLink: req.purchaseLink || '',
            purchaseType: (req.purchaseType as 'Reposição' | 'Obra' | 'Avulso') || 'Reposição',
            requestDate: req.date
        });
        const inCatalog = items.some(i => i.name === req.itemName);
        setIsManualItem(!inCatalog);
        setIsRequestModalOpen(true);
    };

    const handleShowPriceHistory = (item: StockItem) => {
        setSelectedItemForHistory(item);
        setIsPriceHistoryModalOpen(true);
    };

    const handleShowReservations = (e: React.MouseEvent, item: StockItem) => {
        e.stopPropagation();
        if ((item.reservedQuantity || 0) <= 0) return;
        setSelectedItemForReservation(item);
        setIsReservationModalOpen(true);
    };

    const priceHistoryChartData = useMemo(() => {
        if (!selectedItemForHistory?.priceHistory) return [];
        return [...selectedItemForHistory.priceHistory]
            .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .map(entry => ({
                date: new Date(entry.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit' }),
                price: entry.price
            }));
    }, [selectedItemForHistory]);

    const activeReservations = useMemo(() => {
        if (!selectedItemForReservation) return [];
        const itemId = String(selectedItemForReservation.id);

        return checkins
            .filter(c => (c.status === 'Efetivado' || c.status === 'Aberto') && c.details.componentesEstoque?.some((comp: any) => String(comp.itemId) === itemId))
            .map(c => {
                const comp = c.details.componentesEstoque.find((comp: any) => String(comp.itemId) === itemId);
                return {
                    project: c.project,
                    date: c.date,
                    qty: comp?.qty || 0,
                    status: c.status,
                    responsible: c.responsible
                };
            })
            .sort((a, b) => new Date(a.date).getTime() - new Date(a.date).getTime());
    }, [selectedItemForReservation, checkins]);

    if (view === 'visao_geral') {
        const inventoryValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return (
            <div className="space-y-6 animate-fade-in">
                <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                    <div><h2 className="text-2xl font-bold text-gray-900 dark:text-white">Estoque geral</h2><p className="text-xs text-gray-500 font-bold mt-1">Gestão de inventário e movimentações</p></div>
                    <div className="flex bg-white dark:bg-gray-800 p-1 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                        <button onClick={() => setActiveTab('inventario')} className={`px-4 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'inventario' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>Inventário atual</button>
                        <button onClick={() => setActiveTab('historico')} className={`px-4 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'historico' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>Histórico de movimentação</button>
                    </div>
                </header>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    <DashboardCard title="Itens no catálogo" value={items.length.toString()} icon={CubeIcon} color="bg-indigo-500" />
                    <DashboardCard title="Alertas de mínimo" value={items.filter(i => i.quantity <= i.minQuantity).length.toString()} icon={ExclamationTriangleIcon} color="bg-orange-500" />
                    <DashboardCard title="Valor total do estoque" value={formatCurrency(inventoryValue)} icon={DollarIcon} color="bg-green-600" />
                </div>

                {activeTab === 'inventario' ? (
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border dark:border-gray-700 overflow-hidden">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700 font-bold text-[11px] text-gray-500 border-b">
                                <tr>
                                    <th className="px-4 py-4">Foto</th>
                                    <th className="px-4 py-4">Descrição</th>
                                    <th className="px-4 py-4 text-right">Custo unitário</th>
                                    <th className="px-4 py-4 text-center">Saldo</th>
                                    <th className="px-4 py-4 text-center">Saldo mínimo</th>
                                    <th className="px-4 py-4 text-center">Reservado</th>
                                    <th className="px-4 py-4 text-center">Saldo futuro</th>
                                    <th className="px-4 py-4 text-center">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {items.map(item => {
                                    const isLowStock = item.quantity <= item.minQuantity;
                                    const hasReservations = (item.reservedQuantity || 0) > 0;
                                    return (
                                        <tr key={item.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors cursor-pointer group ${isLowStock ? 'bg-red-50/50 dark:bg-red-900/10' : ''}`} onClick={() => handleShowPriceHistory(item)}>
                                            <td className="px-4 py-3"><div className="w-10 h-10 rounded-lg border bg-white dark:bg-gray-900 flex items-center justify-center overflow-hidden">{item.image ? <img src={item.image} className="w-full h-full object-cover" alt="" /> : <PhotographIcon className="w-5 h-5 text-gray-300" />}</div></td>
                                            <td className="px-4 py-3">
                                                <p className="font-bold text-gray-900 dark:text-white group-hover:text-indigo-600 transition-colors">{item.name}</p>
                                                <p className="text-[9px] text-gray-400 font-medium">Clique para ver histórico de custos</p>
                                            </td>
                                            <td className="px-4 py-3 text-right font-bold text-indigo-600">{formatCurrency(item.averagePrice || 0)}</td>
                                            <td className="px-4 py-3 text-center font-black text-gray-900 dark:text-white">{item.quantity}</td>
                                            <td className="px-4 py-3 text-center font-black text-orange-600">{item.minQuantity}</td>
                                            <td 
                                                className={`px-4 py-3 text-center font-bold ${hasReservations ? 'text-amber-600 underline decoration-dotted hover:text-amber-700' : 'text-gray-400'}`}
                                                onClick={(e) => handleShowReservations(e, item)}
                                                title={hasReservations ? "Clique para ver detalhes das reservas" : ""}
                                            >
                                                {item.reservedQuantity || 0}
                                            </td>
                                            <td className="px-4 py-3 text-center font-bold text-indigo-600">{(item.quantity || 0) - (item.reservedQuantity || 0)}</td>
                                            <td className="px-4 py-3 text-center">{isLowStock ? <span className="text-[9px] font-black text-red-600 bg-red-100 px-2 py-1 rounded-full">Reposição</span> : <span className="text-[9px] font-black text-green-600 bg-green-100 px-2 py-1 rounded-full">Normal</span>}</td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="space-y-4">
                        <div className="bg-white dark:bg-gray-800 p-5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex flex-col md:flex-row items-end gap-4">
                            <div className="flex-1 w-full relative" ref={historySuggestionRef}>
                                <label className="block text-[11px] font-bold text-gray-400 mb-1.5 ml-1">Filtrar componente</label>
                                <div className="relative">
                                    <input 
                                        type="text"
                                        autoComplete="off"
                                        placeholder="Digite para buscar componente..."
                                        value={historySearchTerm}
                                        onFocus={() => setShowHistorySuggestions(true)}
                                        onChange={(e) => {
                                            setHistorySearchTerm(e.target.value);
                                            setShowHistorySuggestions(true);
                                            if (e.target.value === '') setHistoryItemId('Todos');
                                        }}
                                        className="w-full h-11 bg-gray-50 dark:bg-gray-900 border border-gray-100 dark:border-gray-700 rounded-xl px-4 pr-10 text-xs font-bold text-gray-700 dark:text-gray-200 outline-none focus:ring-2 focus:ring-indigo-500/20 shadow-sm"
                                    />
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-40">
                                        <SearchIcon className="w-4 h-4" />
                                    </div>
                                </div>

                                {showHistorySuggestions && (
                                    <div className="absolute top-full left-0 z-50 w-full bg-white dark:bg-gray-800 mt-1 rounded-xl shadow-2xl border border-indigo-50 dark:border-gray-700 py-2 max-h-52 overflow-y-auto custom-scrollbar animate-fade-in">
                                        <button
                                            type="button"
                                            onClick={() => handleSelectHistoryItem('Todos')}
                                            className="w-full flex items-center px-4 py-2 text-left hover:bg-indigo-50 dark:hover:bg-indigo-900/20 text-xs font-bold text-gray-700 dark:text-gray-200"
                                        >
                                            Todos os componentes
                                        </button>
                                        <div className="h-px bg-gray-100 dark:bg-gray-700 my-1 mx-2"></div>
                                        {filteredItemsForHistory.map(item => (
                                            <button
                                                key={item.id}
                                                type="button"
