                                            <Line 
                                                type="monotone" 
                                                dataKey="price" 
                                                stroke="#6366f1" 
                                                strokeWidth={3} 
                                                dot={{ r: 4, fill: '#6366f1', strokeWidth: 2, stroke: '#fff' }}
