                            <button onClick={() => setIsReservationModalOpen(false)} className="w-full py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs hover:bg-gray-200 transition-colors">Fechar detalhamento</button>
                        </div>
                    </Modal>
                )}
            </div>
        );
