                                            required 
                                            type="text" 
                                            value={productForm.name} 
                                            onChange={e => setProductForm({...productForm, name: e.target.value})} 
                                            className={editableFieldClass} 
                                            placeholder="Ex: Disjuntor bipolar 20a curva c - schneider" 
