                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {isPriceHistoryModalOpen && selectedItemForHistory && (
                    <Modal title={`Histórico de custos - ${selectedItemForHistory.name}`} onClose={() => setIsPriceHistoryModalOpen(false)} maxWidth="max-w-2xl">
