                        </div>
                    </Modal>
                )}
            </div>
        );
    }

    if (view === 'cadastro') {
        const canManageCatalog = isAdmin || String(currentUser.profileId) === 'vendedor-001';
        return (
            <div className="space-y-6 animate-fade-in">
