                    <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastrar produtos</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1 tracking-wide">Gerenciamento de materiais e equipamentos</p>
                    </div>
