                        <button 
                            onClick={() => {
                                setStockItemToEdit(null);
                                setProductForm({ name: '', ncm: '', quantity: 0, minQuantity: 1, unit: 'un', description: '', image: '', averagePrice: 0, isFixedInBudget: true });
                                setIsProductModalOpen(true);
                            }}
