                                                    <div className={`p-4 ${isHighlight ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-300' : 'bg-slate-50 dark:bg-slate-900/10 border-slate-200 dark:border-slate-800'} border-2 border-dashed rounded-2xl text-center`}>
