                                                            <span className={`text-[10px] font-black ${info.daysSinceLastEvent > 180 ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                        </div>
                                                        <p className="text-[10px] font-black text-slate-700 dark:text-gray-400 mb-2">{info.executedCount >= info.washQtyLimit ? 'Ciclo finalizado ✅' : isHighlight ? 'Oportunidade de Reativação' : 'Aguardando agenda'}</p>
