                                                            <button onClick={() => { setSelectedClient(client); setIsContractDetailModalOpen(true); }} className="text-[11px] font-black text-indigo-600 hover:text-indigo-800 transition-colors flex items-center gap-1">{formatCurrency(info.contractTotalValue)}<ChevronDownIcon className="w-2.5 h-2.5 opacity-50" /></button>
