                                            <div>
                                                <label className="block text-[11px] font-bold text-gray-500 mb-1 ml-1 tracking-tight">Data da 1ª lavagem</label>
                                                <input required type="date" value={scheduleDates[0] || ''} onChange={e => applyFrequency(e.target.value, frequency)} className="w-full rounded-xl bg-white p-3 text-sm font-black shadow-sm border" />
                                            </div>
                                            <div>
                                                <label className="block text-[11px] font-bold text-gray-500 mb-1 ml-1 tracking-tight">Frequência</label>
                                                <select value={frequency} onChange={e => { setFrequency(e.target.value as Frequency); applyFrequency(scheduleDates[0], e.target.value as Frequency); }} className="w-full rounded-xl bg-white p-3 text-sm font-bold shadow-sm border"><option value="trimestral">Trimestral</option><option value="semestral">Semestral</option><option value="anual">Anual</option><option value="manual">Manual</option></select>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 max-h-64 overflow-y-auto pr-1 custom-scrollbar p-1">
                                        {scheduleDates.map((date, idx) => (
                                            <div key={idx} className="relative group">
                                                <span style={{ color: packageColor }} className="absolute -top-2.5 left-3 px-1.5 bg-white text-[8px] font-black z-10 border rounded tracking-tighter">{idx + 1}ª lavagem</span>
                                                <input type="date" value={date} onChange={e => { const newDates = [...scheduleDates]; newDates[idx] = e.target.value; setScheduleDates(newDates); setFrequency('manual'); }} className="w-full rounded-xl bg-gray-50 p-3 text-xs font-black outline-none border-2 border-transparent focus:border-indigo-400 transition-all" />
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex gap-3 pt-4 border-t">
                                        <button type="button" onClick={() => setIsWashModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                                        <button type="submit" disabled={isSaving || !scheduleDates[0]} style={{ backgroundColor: packageColor }} className="flex-[2] py-3 text-white rounded-xl font-black text-xs shadow-lg hover:brightness-110 transition-all">Agendar cronograma</button>
                                    </div>
                                </>
                            ); 
                        })()}
                    </form>
                </Modal>
            )}

            {isPackageModalOpen && (
                <Modal title="Gerenciar planos" onClose={() => { setIsPackageModalOpen(false); setEditingPackage(null); }} maxWidth="max-w-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-4">
                            <h4 className="text-[10px] font-black text-gray-400 uppercase border-b pb-2">Planos cadastrados</h4>
                            <div className="space-y-2 max-h-[350px] overflow-y-auto pr-2 custom-scrollbar">
                                {packages.map(pkg => (
                                    <div key={pkg.id} className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: pkg.color }}></div>
                                            <div>
                                                <p className="text-xs font-black text-gray-800 dark:text-white leading-tight">{pkg.name}</p>
                                                <p className="text-[9px] text-gray-400 font-bold">{pkg.wash_qty} visitas • {formatCurrency(pkg.price_per_plate)}/placa</p>
                                            </div>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => handleEditPackage(pkg)} className="p-1 text-gray-400 hover:text-indigo-600 transition-colors"><EditIcon className="w-4 h-4" /></button>
                                            <button onClick={() => handleDeletePackage(pkg.id)} className="p-1 text-gray-400 hover:text-red-500"><TrashIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <form onSubmit={handleSavePackage} className="space-y-4 bg-gray-50 dark:bg-gray-900/40 p-5 rounded-2xl border">
                            <h4 className="text-[10px] font-black text-indigo-600 uppercase">{editingPackage ? 'Editar plano' : 'Novo plano'}</h4>
                            <div>
                                <FormLabel>Nome do plano</FormLabel>
                                <input required value={packageForm.name} onChange={e => setPackageForm(prev => ({...prev, name: e.target.value}))} className="w-full rounded-xl bg-white p-2.5 text-xs font-bold shadow-sm" placeholder="Ex: Anual Ouro 4x" />
                            </div>
                            <div>
                                <FormLabel>Cor</FormLabel>
                                <div className="grid grid-cols-4 gap-1.5 mt-1">
                                    {PRESET_COLORS.map(color => (
                                        <button key={color.hex} type="button" onClick={() => setPackageForm({...packageForm, color: color.hex})} className={`h-7 rounded-lg border-2 transition-all flex items-center justify-center ${packageForm.color === color.hex ? 'border-indigo-500 scale-105' : 'border-transparent opacity-70'}`} style={{ backgroundColor: color.hex }}>{packageForm.color === color.hex && <CheckCircleIcon className="w-3 h-3 text-white" />}</button>
                                    ))}
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><FormLabel>Qtd. visitas</FormLabel><input type="number" required min="1" value={packageForm.wash_qty} onChange={e => setPackageForm(prev => ({...prev, wash_qty: parseInt(e.target.value) || 1}))} className="w-full rounded-xl bg-white p-2.5 text-xs font-bold" /></div>
                                <div><FormLabel>V. placa (R$)</FormLabel><input type="number" step="0.01" required value={packageForm.price_per_plate || ''} onChange={e => setPackageForm(prev => ({...prev, price_per_plate: parseFloat(e.target.value) || 0}))} className="w-full rounded-xl bg-white p-2.5 text-xs font-bold text-emerald-600" /></div>
                            </div>
                            <button type="submit" disabled={isSaving} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] shadow-lg uppercase tracking-widest">{isSaving ? 'Salvando...' : (editingPackage ? 'Atualizar' : 'Criar')}</button>
                        </form>
                    </div>
                </Modal>
            )}

            {isLaunchServiceModalOpen && (
                <Modal title="Vincular ou Renovar Plano" onClose={() => setIsLaunchServiceModalOpen(false)} maxWidth="max-w-3xl">
                    <form onSubmit={handleLaunchService} className="space-y-6 pt-2">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <SectionHeader icon={<UsersIcon />} title="Identificação" />
                                <div>
                                    <FormLabel>Cliente selecionado</FormLabel>
                                    <select 
                                        required 
                                        disabled={isClientLocked} 
                                        value={launchServiceForm.clientId} 
                                        onChange={e => setLaunchServiceForm(prev => ({...prev, clientId: e.target.value}))} 
                                        className={`w-full rounded-xl bg-gray-50 dark:bg-gray-700 p-3 text-sm font-bold shadow-sm ${isClientLocked ? 'opacity-70 cursor-not-allowed border-none' : 'border border-gray-200'}`}
                                    >
                                        <option value="">Escolha...</option>
                                        {clients.map(c => <option key={c.id} value={c.id}>{c.name} ({c.plates_count} placas)</option>)}
                                    </select>
                                </div>
                                <div>
                                    <FormLabel>Última atividade registrada</FormLabel>
                                    {(() => {
                                        const client = clients.find(c => c.id === launchServiceForm.clientId);
                                        if (!client) return <p className="p-3 bg-gray-50 dark:bg-gray-800 rounded-xl text-xs text-gray-400 italic">Selecione um cliente...</p>;
                                        const info = getClientPackageInfo(client);
                                        return (
                                            <div className="p-3 bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl flex items-center justify-between">
                                                <div className="flex items-center gap-2">
                                                    <ClockIcon className="w-4 h-4 text-gray-400" />
                                                    <span className="text-xs font-bold text-gray-700 dark:text-gray-200">{info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone: 'UTC'}) : 'Sem registro'}</span>
                                                </div>
                                                <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${info.daysSinceLastEvent > 180 ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                            </div>
                                        );
                                    })()}
                                </div>
                                <div>
                                    <FormLabel>Data base de instalação (Término)</FormLabel>
                                    <input 
                                        readOnly 
                                        required 
                                        type="date" 
                                        value={launchServiceForm.installationEndDate} 
                                        className="w-full rounded-xl bg-gray-100 dark:bg-gray-800 p-3 text-sm font-bold shadow-sm opacity-70 cursor-not-allowed border-none outline-none" 
                                    />
                                </div>
                            </div>

                            <div className="space-y-4">
                                <SectionHeader icon={<SparklesIcon />} title="Planos vigentes" color="bg-cyan-600" />
                                {packages.length > 0 ? (
                                    <div className="space-y-2 max-h-[350px] overflow-y-auto pr-1 custom-scrollbar">
                                        {packages.map(p => (
                                            <div 
                                                key={p.id}
                                                onClick={() => setLaunchServiceForm(prev => ({ ...prev, packageId: p.id }))}
                                                className={`p-4 rounded-2xl border-2 transition-all cursor-pointer group relative overflow-hidden ${launchServiceForm.packageId === p.id ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/40 shadow-lg scale-[1.02]' : 'border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 hover:border-indigo-200'}`}
                                            >
                                                <div className="absolute top-0 right-0 w-12 h-12 flex items-center justify-center -mr-2 -mt-2 opacity-10 group-hover:opacity-20 transition-opacity">
                                                    <SparklesIcon className="w-full h-full" style={{ color: p.color }} />
                                                </div>
                                                <div className="flex items-center gap-3">
                                                    <div className="w-4 h-4 rounded-full shadow-sm shrink-0" style={{ backgroundColor: p.color }} />
                                                    <div className="flex-1">
                                                        <h4 className="text-sm font-black text-gray-800 dark:text-white">{p.name}</h4>
                                                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">{p.wash_qty} visitas incluídas</p>
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="text-xs font-black text-indigo-600 dark:text-indigo-400">{formatCurrency(p.price_per_plate)}</p>
                                                        <p className="text-[8px] font-bold text-gray-400 uppercase">por placa</p>
                                                    </div>
                                                </div>
                                                {launchServiceForm.packageId === p.id && (
                                                    <div className="absolute bottom-1 right-2 animate-bounce">
                                                        <CheckCircleIcon className="w-4 h-4 text-indigo-600" />
                                                    </div>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="p-6 bg-amber-50 dark:bg-amber-900/10 border-2 border-dashed border-amber-200 dark:border-amber-800 rounded-3xl text-center">
                                        <ExclamationTriangleIcon className="w-10 h-10 text-amber-500 mx-auto mb-3" />
                                        <h4 className="text-sm font-bold text-amber-800 dark:text-amber-400 mb-1">Nenhum plano configurado</h4>
                                        <p className="text-[10px] text-amber-600 font-medium mb-4 leading-relaxed">Você precisa criar pacotes de serviço (ex: Anual 4x) para poder vincular ou renovar clientes.</p>
                                        <button 
                                            type="button" 
                                            onClick={() => { setIsLaunchServiceModalOpen(false); setIsPackageModalOpen(true); }}
                                            className="px-6 py-2 bg-amber-500 text-white rounded-xl font-black text-[10px] uppercase shadow-md shadow-amber-200 hover:bg-amber-600 transition-all"
                                        >
                                            Criar planos agora
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>

                        {launchServiceForm.clientId && launchServiceForm.packageId && (() => { 
                            const client = clients.find(c => c.id === launchServiceForm.clientId); 
                            const pkg = packages.find(p => p.id === launchServiceForm.packageId); 
                            if (!client || !pkg) return null; 
                            const subtotalPlacas = pkg.price_per_plate * client.plates_count; 
                            const totalPlano = subtotalPlacas * pkg.wash_qty; 
                            const totalGeral = totalPlano + Number(launchServiceForm.travelCost || 0); 
                            return (
                                <div className="p-6 bg-indigo-50 dark:bg-indigo-900/30 rounded-3xl border-2 border-indigo-100 dark:border-indigo-800 animate-fade-in">
                                    <h4 className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ClipboardListIcon className="w-3.5 h-3.5" /> Memorial de cálculo da renovação</h4>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                        <div className="space-y-2">
                                            <div className="flex justify-between items-center text-[11px] font-bold text-gray-600 dark:text-gray-300">
                                                <span>Base ({client.plates_count} placas x {formatCurrency(pkg.price_per_plate)})</span>
                                                <span className="text-gray-800 dark:text-white">{formatCurrency(subtotalPlacas)} /visita</span>
                                            </div>
                                            <div className="flex justify-between items-center text-[11px] font-bold text-gray-600 dark:text-gray-300 border-b border-indigo-100 dark:border-indigo-800 pb-2">
                                                <span>Ciclo ({pkg.wash_qty} visitas)</span>
                                                <span className="text-gray-800 dark:text-white font-black">{formatCurrency(totalPlano)}</span>
                                            </div>
                                            <div className="py-2">
                                                <label className="block text-[10px] font-black text-indigo-500 dark:text-indigo-400 mb-1 ml-0.5 uppercase">Taxa Deslocamento (Opcional)</label>
                                                <div className="relative">
                                                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-indigo-400 font-bold text-xs">R$</span>
                                                    <input type="number" step="0.01" value={launchServiceForm.travelCost || ''} onChange={e => setLaunchServiceForm(prev => ({...prev, travelCost: parseFloat(e.target.value) || 0}))} className="w-full rounded-xl bg-white dark:bg-gray-900 p-2.5 pl-9 text-xs font-black text-indigo-600 dark:text-indigo-400 shadow-inner border border-indigo-100 dark:border-indigo-800 outline-none focus:ring-2 focus:ring-indigo-500/20" placeholder="0,00" />
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex flex-col justify-center items-center md:items-end border-t md:border-t-0 md:border-l border-indigo-200 dark:border-indigo-800 md:pl-8 pt-4 md:pt-0">
                                            <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest leading-none mb-2">Investimento Total do Cliente</p>
                                            <p className="text-4xl font-black text-indigo-800 dark:text-indigo-100 leading-none">{formatCurrency(totalGeral)}</p>
                                            <p className="text-[9px] font-bold text-indigo-400 mt-2 text-right">Este valor será lançado como receita pendente no financeiro após a confirmação.</p>
                                        </div>
                                    </div>
                                </div>
                            ); 
                        })()}
                        <div className="flex gap-3 pt-6 border-t dark:border-gray-700">
                            <button type="button" onClick={() => setIsLaunchServiceModalOpen(false)} className="flex-1 py-4 bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-300 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-gray-200 transition-all">Cancelar</button>
                            <button 
                                type="submit" 
                                disabled={isSaving || !launchServiceForm.packageId} 
                                className={`flex-[2] py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2 ${launchServiceForm.packageId ? 'bg-cyan-600 text-white shadow-cyan-600/20 hover:bg-cyan-700' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}
                            >
                                <CheckCircleIcon className="w-5 h-5" /> Confirmar Renovação
                            </button>
                        </div>
                    </form>
                </Modal>
            )}
        </div>
    );
}

