    { name: 'Indigo', hex: '#6366f1' },
    { name: 'Esmeralda', hex: '#10b981' },
    { name: 'Âmbar', hex: '#f59e0b' },
    { name: 'Rosa', hex: '#f43f5e' },
    { name: 'Céu', hex: '#0ea5e9' },
    { name: 'Violeta', hex: '#8b5cf6' },
