    { name: 'Violeta', hex: '#8b5cf6' },
    { name: 'Laranja', hex: '#f97316' },
    { name: 'Ouro', hex: '#d4af37' }
];

type PendingAction = {
    type: 'execute' | 'delete' | 'update';
    record: LavagemRecord;
};

type Frequency = 'trimestral' | 'semestral' | 'anual' | 'manual';

export default function LavagemPage({ currentUser }: { currentUser: User }) {
    const [packages, setPackages] = useState<LavagemPackage[]>([]);
    const [clients, setClients] = useState<LavagemClient[]>([]);
    const [records, setRecords] = useState<LavagemRecord[]>([]);
    const [contracts, setContracts] = useState<LavagemContract[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingCep, setIsLoadingCep] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Modais
    const [isClientModalOpen, setIsClientModalOpen] = useState(false);
    const [isPackageModalOpen, setIsPackageModalOpen] = useState(false);
    const [isWashModalOpen, setIsWashModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [isLaunchServiceModalOpen, setIsLaunchServiceModalOpen] = useState(false);
    const [isEditWashDateModalOpen, setIsEditWashDateModalOpen] = useState(false);
    const [isConfirmActionModalOpen, setIsConfirmActionModalOpen] = useState(false);
    const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);

    // Estados de edição/seleção
    const [editingClient, setEditingClient] = useState<LavagemClient | null>(null);
    const [editingPackage, setEditingPackage] = useState<LavagemPackage | null>(null);
    const [selectedClientForModal, setSelectedClientForModal] = useState<LavagemClient | null>(null);
    const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
    const [isClientLocked, setIsClientLocked] = useState(false);
    const [modalMessage, setModalMessage] = useState('');

    // Abas e Filtros
    const [activeTab, setActiveTab] = useState<'timeline' | 'oportunidades'>('timeline');
    const [filterStatus, setFilterStatus] = useState('Todos');
    const [usePeriodFilter, setUsePeriodFilter] = useState(false);
    const [periodStart, setPeriodStart] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]); 
    const [periodEnd, setPeriodEnd] = useState(new Date().toISOString().split('T')[0]);

    // Formulários
    const [clientForm, setClientForm] = useState<Partial<LavagemClient>>({
        name: '', phone: '', cep: '', address: '', address_number: '', complement: '', city: '', plates_count: 0, installation_end_date: '', observations: ''
    });
    const [packageForm, setPackageForm] = useState({
        name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0
    });
    const [scheduleDates, setScheduleDates] = useState<string[]>([]);
    const [frequency, setFrequency] = useState<Frequency>('semestral');
    const [launchServiceForm, setLaunchServiceForm] = useState({ 
        clientId: '', 
        packageId: '',
        installationEndDate: new Date().toISOString().split('T')[0],
        travelCost: 0
    });
    const [editWashValue, setEditWashValue] = useState<{ date: string, status: 'scheduled' | 'executed' | 'cancelled' }>({ date: '', status: 'scheduled' });

    const lastFetchedCep = useRef('');

    const loadData = async () => {
        setIsLoading(true);
        try {
            const isAdmin = String(currentUser.profileId) === '001';
            const [pkgData, cliData, recData, contractData] = await Promise.all([
                dataService.getAll<LavagemPackage>('lavagem_packages', currentUser.id, isAdmin),
                dataService.getAll<LavagemClient>('lavagem_clients', currentUser.id, isAdmin),
                dataService.getAll<LavagemRecord>('lavagem_records', currentUser.id, isAdmin),
                dataService.getAll<LavagemContract>('lavagem_contracts', undefined, true) 
            ]);
            setPackages(pkgData.sort((a, b) => (a.wash_qty - b.wash_qty) || a.name.localeCompare(b.name)));
            setClients(cliData.sort((a,b) => a.name.localeCompare(b.name)));
            setRecords(recData);
            setContracts(contractData || []);
        } catch (e) { 
            console.error(e); 
        } finally { 
            setIsLoading(false); 
        }
    };

    useEffect(() => { loadData(); }, [currentUser.id]);

    // Busca CEP
    useEffect(() => {
        const cleanCep = (clientForm.cep || '').replace(/\D/g, '');
        if (cleanCep.length === 8 && isClientModalOpen && cleanCep !== lastFetchedCep.current) {
            const fetchCep = async () => {
                setIsLoadingCep(true);
                try {
                    const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
                    const data = await response.json();
                    if (!data.erro) {
                        lastFetchedCep.current = cleanCep;
                        setClientForm(prev => ({ 
                            ...prev, 
                            address: data.logradouro || prev.address, 
                            city: data.localidade || prev.city 
                        }));
                    }
                } catch (e) { console.error(e); } finally { setIsLoadingCep(false); }
            };
            fetchCep();
        }
    }, [clientForm.cep, isClientModalOpen]);

    const getClientPackageInfo = (client: LavagemClient) => {
        const pkg = packages.find(p => p.id === client.package_id);
        const clientRecords = records.filter(r => r.client_id === client.id);
        const launchDate = client.package_launch_date || '1970-01-01';
        const currentCycleRecords = clientRecords.filter(r => (r.created_at || r.date) >= launchDate);
        const executedCount = currentCycleRecords.filter(r => r.status === 'executed').length;
        const washQtyLimit = client.contract_wash_qty || pkg?.wash_qty || 0;
        const pricePerPlate = client.contract_price_per_plate || pkg?.price_per_plate || 0;
        const allScheduled = currentCycleRecords.filter(r => r.status === 'scheduled').sort((a, b) => a.date.localeCompare(b.date));
        const nextScheduled = allScheduled[0];
        const pendingToScheduleCount = Math.max(0, washQtyLimit - executedCount - allScheduled.length);

        const subtotalPlacas = pricePerPlate * (client.plates_count || 0);
        const contractTotalValue = (subtotalPlacas * washQtyLimit) + (client.travel_cost || 0);

        const lastExecutedWash = clientRecords
            .filter(r => r.status === 'executed')
            .sort((a, b) => b.date.localeCompare(a.date))[0];

        const lastEventDate = lastExecutedWash?.date || client.installation_end_date;
        let daysSinceLastEvent = 0;
        let isHighOpportunity = false;
        let isModerateOpportunity = false;

        if (lastEventDate) {
            const dateObj = new Date(lastEventDate);
            const today = new Date();
            const diffTime = Math.abs(today.getTime() - dateObj.getTime());
            daysSinceLastEvent = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            isModerateOpportunity = daysSinceLastEvent >= 180;
            isHighOpportunity = daysSinceLastEvent >= 330;
        }

        const totalAccumulated = contracts
            .filter(c => c.client_id === client.id)
            .reduce((acc, c) => acc + Number(c.total_value), 0);

        return { 
            pkg, 
            executedCount, 
            washQtyLimit, 
            nextScheduled, 
            allScheduled, 
            currentCycleRecords, 
            pendingToScheduleCount, 
            contractTotalValue, 
            pricePerPlate,
            totalAccumulated,
            travelCost: client.travel_cost || 0,
            isHighOpportunity,
            isModerateOpportunity,
            daysSinceLastEvent,
            lastEventDate,
            hasNeverWashed: !lastExecutedWash
        };
    };

    const visibleClientsWithInfo = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];

        return clients.map(client => ({
            client,
            info: getClientPackageInfo(client)
        })).filter(({ client, info }) => {
            if (activeTab === 'oportunidades' && client.package_id) return false;
            if (activeTab === 'timeline' && !client.package_id) return false;
            if (searchTerm && !client.name.toLowerCase().includes(searchTerm.toLowerCase()) && !(client.city || '').toLowerCase().includes(searchTerm.toLowerCase())) return false;

            if (activeTab === 'timeline') {
                const isFinished = info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0;
                const hasOverdue = info.allScheduled.some(r => r.date < todayStr);

                if (filterStatus !== 'Todos') {
                    if (filterStatus === 'Atrasados' && !hasOverdue) return false;
                    if (filterStatus === 'Ciclo Finalizado' && !isFinished) return false;
                    if (filterStatus === 'Com agendamentos' && info.allScheduled.length === 0) return false;
                    if (filterStatus === 'Sem Agendamento' && info.pendingToScheduleCount === 0) return false;
                }

                if (usePeriodFilter) {
                    const scheduledInPeriod = info.allScheduled.some(r => r.date >= periodStart && r.date <= periodEnd);
                    const executedInPeriod = info.currentCycleRecords.some(r => r.status === 'executed' && r.date >= periodStart && r.date <= periodEnd);
                    const launchInPeriod = client.package_launch_date && client.package_launch_date.split('T')[0] >= periodStart && client.package_launch_date.split('T')[0] <= periodEnd;
                    if (!scheduledInPeriod && !executedInPeriod && !launchInPeriod) return false;
                }
            }
            return true;
        });
    }, [clients, packages, records, contracts, activeTab, searchTerm, filterStatus, usePeriodFilter, periodStart, periodEnd]);

    const handleSaveClient = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemClient = {
                id: editingClient ? editingClient.id : `wash-cli-${Date.now()}`,
                owner_id: currentUser.id,
                name: clientForm.name!,
                phone: clientForm.phone,
                cep: clientForm.cep!,
                address: clientForm.address!,
                address_number: clientForm.address_number!,
                complement: clientForm.complement!,
                city: clientForm.city!,
                plates_count: clientForm.plates_count!,
                observations: clientForm.observations,
                installation_end_date: clientForm.installation_end_date || undefined,
                package_id: editingClient?.package_id,
                contract_wash_qty: editingClient?.contract_wash_qty,
                contract_price_per_plate: editingClient?.contract_price_per_plate,
                package_launch_date: editingClient?.package_launch_date,
                travel_cost: editingClient?.travel_cost
            };
            await dataService.save('lavagem_clients', data);
            setIsClientModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleSavePackage = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemPackage = {
                id: editingPackage ? editingPackage.id : `wash-pkg-${Date.now()}`,
                owner_id: currentUser.id,
                name: packageForm.name,
                color: packageForm.color,
                wash_qty: packageForm.wash_qty,
                price_per_plate: packageForm.price_per_plate
            };
            await dataService.save('lavagem_packages', data);
            setEditingPackage(null);
            setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 });
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleOpenLaunchModal = (clientId: string = '') => {
        const client = clients.find(c => c.id === clientId);
        setLaunchServiceForm({ 
            clientId, 
            packageId: '', 
            installationEndDate: client?.installation_end_date || new Date().toISOString().split('T')[0],
            travelCost: 0
        });
        setIsClientLocked(!!clientId);
        setIsLaunchServiceModalOpen(true);
    };

    const handleLaunchService = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!launchServiceForm.clientId || !launchServiceForm.packageId) return;
        const client = clients.find(c => c.id === launchServiceForm.clientId);
        const selectedPkg = packages.find(p => p.id === launchServiceForm.packageId);
        if (!client || !selectedPkg) return;

        setIsSaving(true);
        try {
            const launchDate = new Date();
            const platesTotal = selectedPkg.price_per_plate * (client.plates_count || 0);
            const contractTotal = (platesTotal * selectedPkg.wash_qty) + Number(launchServiceForm.travelCost || 0);

            await dataService.save('lavagem_clients', {
                ...client,
                package_id: selectedPkg.id,
                contract_price_per_plate: selectedPkg.price_per_plate,
                contract_wash_qty: selectedPkg.wash_qty,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                package_launch_date: launchDate.toISOString()
            });

            await dataService.save('lavagem_contracts', {
                id: `cont-${Date.now()}`,
                client_id: client.id,
                package_name: selectedPkg.name,
                total_value: contractTotal,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                created_at: launchDate.toISOString()
            });

            await loadData();
            setIsLaunchServiceModalOpen(false);
            setModalMessage("Plano vinculado com sucesso!");
            setSuccessModalOpen(true);
        } finally { setIsSaving(false); }
    };

    const executePendingAction = async () => {
        if (!pendingAction) return;
        setIsSaving(true);
        try {
            if (pendingAction.type === 'execute') await dataService.save('lavagem_records', { ...pendingAction.record, status: 'executed' });
            else if (pendingAction.type === 'delete') await dataService.delete('lavagem_records', pendingAction.record.id);
            else if (pendingAction.type === 'update') await dataService.save('lavagem_records', { ...pendingAction.record, date: editWashValue.date, status: editWashValue.status });
            await loadData();
            setIsConfirmActionModalOpen(false);
            setIsEditWashDateModalOpen(false);
            setPendingAction(null);
        } finally { setIsSaving(false); }
    };

    if (isLoading) return <div className="flex justify-center p-20"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-cyan-600"></div></div>;

    const inputClass = "w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 p-2.5 text-xs font-bold text-gray-800 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all shadow-sm";

    const timelineGroups = useMemo(() => {
        if (activeTab !== 'timeline') return [];
        const groups: Record<string, { label: string, items: any[] }> = {
            'pending': { label: 'Ação necessária / Ciclos pendentes', items: [] }
        };
        visibleClientsWithInfo.forEach(item => {
            const nextDate = item.info.nextScheduled?.date || null;
            if (nextDate) {
                const date = new Date(nextDate);
                const key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
                const label = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                if (!groups[key]) groups[key] = { label: toSentenceCase(label), items: [] };
                groups[key].items.push(item);
            } else {
                groups['pending'].items.push(item);
            }
        });
        return Object.keys(groups).sort((a, b) => a === 'pending' ? -1 : a.localeCompare(b)).map(k => ({ key: k, ...groups[k] })).filter(g => g.items.length > 0);
    }, [visibleClientsWithInfo, activeTab]);

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <header className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-6">
                <div className="flex items-center gap-5 flex-1">
                    <div className="p-4 bg-cyan-600 text-white rounded-2xl shadow-lg shadow-cyan-600/20"><SparklesIcon className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Gestão de Lavagens</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1">Recorrência solar inteligente</p>
                    </div>
                </div>
                <div className="flex flex-wrap justify-center gap-3">
                    <button onClick={() => setIsPackageModalOpen(true)} className="flex items-center gap-2 px-5 py-2.5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Planos</button>
                    <button onClick={() => { setEditingClient(null); setClientForm({name:'', phone:'', cep:'', address:'', address_number:'', complement:'', city:'', plates_count:0, installation_end_date: '', observations: ''}); setIsClientModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Novo cliente</button>
                    <button onClick={() => handleOpenLaunchModal()} className="flex items-center gap-2 px-8 py-2.5 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-xl shadow-cyan-600/20 hover:bg-cyan-700 transition-all active:scale-95">Lançar serviço</button>
                </div>
            </header>

            <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                <button onClick={() => setActiveTab('timeline')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'timeline' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><CalendarIcon className="w-4 h-4" /> Timeline de Serviços</button>
                <button onClick={() => setActiveTab('oportunidades')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'oportunidades' ? 'bg-amber-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><TrendUpIcon className="w-4 h-4" /> Oportunidades</button>
            </div>

            {activeTab === 'timeline' ? (
                <div className="space-y-10">
                    {timelineGroups.map(group => (
                        <section key={group.key}>
                            <div className="flex items-center gap-4 mb-6">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white shadow-md ${group.key === 'pending' ? 'bg-slate-500' : 'bg-cyan-600'}`}>
                                    {group.key === 'pending' ? <ClockIcon className="w-6 h-6" /> : <CalendarIcon className="w-6 h-6" />}
                                </div>
                                <h3 className="text-lg font-black text-gray-800 dark:text-white">{group.label}</h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {group.items.map(({ client, info }) => {
                                    const packageColor = info.pkg?.color || '#94a3b8';
                                    const isHighlight = group.key === 'pending' && (info.isModerateOpportunity || info.isHighOpportunity);

                                    return (
                                        <div 
                                            key={client.id} 
                                            className={`bg-white dark:bg-gray-800 rounded-3xl border p-5 shadow-sm hover:shadow-xl transition-all flex flex-col relative ${isHighlight ? 'border-amber-400 ring-4 ring-amber-500/5' : 'border-gray-100 dark:border-gray-700'}`}
                                        >
                                            <div className="flex justify-between items-start mb-4">
                                                <div>
                                                    <h4 className="font-black text-gray-800 dark:text-white text-base">{client.name}</h4>
                                                    <p className="text-[10px] text-gray-400 font-bold flex items-center gap-1"><MapPinIcon className="w-3 h-3" /> {client.city}</p>
                                                </div>
                                                <button onClick={() => { setEditingClient(client); setClientForm({...client, installation_end_date: client.installation_end_date || ''}); setIsClientModalOpen(true); }} className="p-1.5 text-gray-300 hover:text-cyan-600"><EditIcon className="w-4 h-4" /></button>
                                            </div>

                                            <div className="bg-gray-50 dark:bg-gray-900/40 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 mb-4">
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-[9px] font-black text-gray-400 uppercase">{info.hasNeverWashed ? 'Desde Instalação' : 'Última Lavagem'}</span>
                                                    <span className={`text-[10px] font-black ${info.daysSinceLastEvent > 180 ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                </div>
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                                                    <ClockIcon className="w-3.5 h-3.5 text-gray-400" />
                                                    {info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : 'Sem registro'}
                                                </p>
                                            </div>

                                            {info.allScheduled.length > 0 ? (
                                                <div style={{ backgroundColor: packageColor }} className="rounded-2xl p-3 text-white">
                                                    <p className="text-[9px] font-black opacity-80 mb-2">Próximo Agendamento</p>
                                                    <div className="flex justify-between items-center bg-white/10 p-2 rounded-xl">
                                                        <span className="text-xs font-black">{new Date(info.nextScheduled.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</span>
                                                        <div className="flex gap-1">
                                                            <button onClick={() => { setPendingAction({ type: 'execute', record: info.nextScheduled }); setIsConfirmActionModalOpen(true); }} className="p-1 bg-white text-indigo-600 rounded-lg shadow-sm"><CheckCircleIcon className="w-4 h-4" /></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className={`p-4 rounded-2xl border-2 border-dashed text-center ${isHighlight ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
                                                    <p className="text-[10px] font-black text-gray-500 mb-3">{isHighlight ? 'Sugerir Nova Lavagem' : 'Sem agendamentos'}</p>
                                                    <button onClick={() => handleOpenLaunchModal(client.id)} className={`w-full py-2 rounded-xl font-black text-[10px] uppercase shadow-md ${isHighlight ? 'bg-amber-500 text-white' : 'bg-slate-500 text-white'}`}>
                                                        {info.executedCount >= info.washQtyLimit ? 'Renovar Plano' : 'Lançar Novo Ciclo'}
                                                    </button>
                                                </div>
                                            )}

                                            <button onClick={() => { setSelectedClientForModal(client); setIsHistoryModalOpen(true); }} className="mt-4 w-full py-2 text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 rounded-xl hover:bg-gray-50 flex items-center justify-center gap-1.5">
                                                <ClipboardListIcon className="w-3 h-3" /> Histórico Completo
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        </section>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {visibleClientsWithInfo.map(({ client, info }) => (
                        <div key={client.id} className="bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 p-5 shadow-sm hover:shadow-xl transition-all flex flex-col">
                            <h4 className="font-black text-gray-800 dark:text-white mb-1">{client.name}</h4>
                            <p className="text-[10px] text-gray-400 font-bold mb-4">{client.city}</p>
                            <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-xl mb-4 text-center">
                                <span className="text-[9px] font-bold text-gray-400 block mb-1">Potencial</span>
                                <span className="text-xl font-black text-gray-700 dark:text-white">{client.plates_count} Placas</span>
                            </div>
                            <button onClick={() => handleOpenLaunchModal(client.id)} className="w-full py-3 bg-amber-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-amber-500/20">Lançar Plano</button>
                        </div>
                    ))}
                </div>
            )}

            {/* Modais de Formulário */}
            {isClientModalOpen && (
                <Modal title={editingClient ? "Editar Cliente" : "Novo Cliente Solar"} onClose={() => setIsClientModalOpen(false)} maxWidth="max-w-2xl">
                    <form onSubmit={handleSaveClient} className="space-y-4 pt-2">
                        <SectionHeader icon={<UsersIcon />} title="Identificação" />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><FormLabel>Nome Completo</FormLabel><input required value={clientForm.name} onChange={e => setClientForm({...clientForm, name: e.target.value})} className={inputClass} /></div>
                            <div><FormLabel>WhatsApp</FormLabel><input value={clientForm.phone} onChange={e => setClientForm({...clientForm, phone: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<MapPinIcon />} title="Endereço" color="bg-teal-600" />
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="col-span-1"><FormLabel>CEP</FormLabel><input value={clientForm.cep} onChange={e => setClientForm({...clientForm, cep: e.target.value})} className={inputClass} /></div>
                            <div className="col-span-2 md:col-span-3"><FormLabel>Logradouro</FormLabel><input value={clientForm.address} onChange={e => setClientForm({...clientForm, address: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<BoltIcon />} title="Projeto" color="bg-amber-600" />
                        <div className="grid grid-cols-2 gap-4">
                            <div><FormLabel>Qtd Placas</FormLabel><input type="number" value={clientForm.plates_count} onChange={e => setClientForm({...clientForm, plates_count: parseInt(e.target.value)||0})} className={inputClass} /></div>
                            <div><FormLabel>Data Instalação</FormLabel><input type="date" value={clientForm.installation_end_date} onChange={e => setClientForm({...clientForm, installation_end_date: e.target.value})} className={inputClass} /></div>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsClientModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-black text-xs shadow-lg">Salvar Cadastro</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isPackageModalOpen && (
                <Modal title="Planos de Lavagem" onClose={() => setIsPackageModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-3">
                            <h4 className="text-[10px] font-black text-gray-400 uppercase border-b pb-2">Ativos</h4>
                            <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                                {packages.map(pkg => (
                                    <div key={pkg.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: pkg.color }}></div>
                                            <span className="text-xs font-black text-gray-800 dark:text-white">{pkg.name}</span>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => handleEditPackage(pkg)} className="p-1 text-gray-400 hover:text-indigo-600"><EditIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <form onSubmit={handleSavePackage} className="space-y-4 bg-gray-50 dark:bg-gray-800/40 p-4 rounded-2xl border">
                            <h4 className="text-[10px] font-black text-indigo-600 uppercase">{editingPackage ? 'Editar' : 'Novo'}</h4>
                            <div><FormLabel>Nome do Plano</FormLabel><input required value={packageForm.name} onChange={e => setPackageForm({...packageForm, name: e.target.value})} className={inputClass} /></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><FormLabel>Visitas</FormLabel><input type="number" required value={packageForm.wash_qty} onChange={e => setPackageForm({...packageForm, wash_qty: parseInt(e.target.value)||1})} className={inputClass} /></div>
                                <div><FormLabel>Preço/Placa</FormLabel><input type="number" step="0.01" value={packageForm.price_per_plate} onChange={e => setPackageForm({...packageForm, price_per_plate: parseFloat(e.target.value)||0})} className={inputClass} /></div>
                            </div>
                            <button type="submit" className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-xs">Salvar Plano</button>
                        </form>
                    </div>
                </Modal>
            )}

            {isLaunchServiceModalOpen && (
                <Modal title="Lançar Ciclo de Serviço" onClose={() => setIsLaunchServiceModalOpen(false)} maxWidth="max-w-md">
                    <form onSubmit={handleLaunchService} className="space-y-5 pt-2">
                        <div>
                            <FormLabel>Cliente</FormLabel>
                            <select required disabled={isClientLocked} value={launchServiceForm.clientId} onChange={e => setLaunchServiceForm({...launchServiceForm, clientId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <FormLabel>Plano de Lavagens</FormLabel>
                            <select required value={launchServiceForm.packageId} onChange={e => setLaunchServiceForm({...launchServiceForm, packageId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {packages.map(p => <option key={p.id} value={p.id}>{p.name} ({p.wash_qty}x)</option>)}
                            </select>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsLaunchServiceModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" className="flex-[2] py-3 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-lg">Confirmar Lançamento</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isHistoryModalOpen && selectedClientForModal && (
                <Modal title={`Histórico: ${selectedClientForModal.name}`} onClose={() => setIsHistoryModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="space-y-4 pt-1">
                        <div className="max-h-[400px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
                            {records.filter(r => r.client_id === selectedClientForModal.id).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                                <div key={record.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border border-gray-100 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${record.status === 'executed' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                            {record.status === 'executed' ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                        </div>
                                        <div>
                                            <p className="text-xs font-black text-gray-800 dark:text-white">Lavagem em {new Date(record.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</p>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase">{record.status === 'executed' ? 'Concluída' : 'Agendada'}</p>
                                        </div>
                                    </div>
                                    <button onClick={async () => { if(confirm('Remover registro?')) { await dataService.delete('lavagem_records', record.id); loadData(); } }} className="p-2 text-gray-300 hover:text-red-500"><TrashIcon className="w-5 h-5" /></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </Modal>
            )}

            {isConfirmActionModalOpen && pendingAction && (
                <Modal title="Confirmar" onClose={() => setIsConfirmActionModalOpen(false)} maxWidth="max-w-sm">
                    <div className="text-center p-4 space-y-6">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-indigo-50 text-indigo-600"><CheckCircleIcon className="w-10 h-10" /></div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Marcar como concluída?</h3>
                        <div className="flex gap-4">
                            <button onClick={() => setIsConfirmActionModalOpen(false)} className="flex-1 py-3 bg-gray-100 rounded-xl font-bold text-sm">Não</button>
                            <button onClick={executePendingAction} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg">Sim, confirmar</button>
                        </div>
                    </div>
                </Modal>
            )}

            {isSuccessModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 animate-fade-in">
                    <div className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-2xl max-w-sm w-full text-center space-y-6">
                        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto animate-bounce"><CheckCircleIcon className="w-12 h-12" /></div>
                        <h3 className="text-xl font-black text-gray-800 dark:text-white">Concluído!</h3>
                        <p className="text-sm text-gray-500 font-bold">{modalMessage}</p>
                        <button onClick={() => setSuccessModalOpen(false)} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest">Entendido</button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
    SparklesIcon, PlusIcon, TrashIcon, EditIcon, 
    CalendarIcon, MapIcon, BoltIcon, CheckCircleIcon, 
    XCircleIcon, SearchIcon, ClockIcon, DollarIcon,
    ChevronDownIcon, HomeIcon, MapPinIcon, UsersIcon, ClipboardListIcon,
    ExclamationTriangleIcon, FilterIcon, ArrowLeftIcon, TrendUpIcon, StarIcon,
    DocumentReportIcon, PhoneIcon
} from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { dataService } from '../services/dataService';
import type { User, LavagemPackage, LavagemClient, LavagemRecord, FinancialCategory, LavagemContract } from '../types';

const toSentenceCase = (str: string) => {
    if (!str) return '';
    const clean = str.toLowerCase();
    return clean.charAt(0).toUpperCase() + clean.slice(1);
};

const formatCurrency = (value: number) => {
    if (value === undefined || value === null || isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const FormLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="block text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-1 ml-0.5 tracking-tight">{children}</label>
);

const SectionHeader: React.FC<{ icon: React.ReactElement<any>; title: string; color?: string; rightElement?: React.ReactNode }> = ({ icon, title, color = "bg-indigo-600", rightElement }) => {
    const isHex = color?.startsWith('#') ?? false;
    return (
        <div className="flex items-center justify-between mb-3 pb-1 border-b border-gray-100 dark:border-gray-700/50">
            <div className="flex items-center gap-2">
                <div 
                    className={`p-1 rounded-lg text-white ${!isHex ? color : ''}`}
                    style={isHex ? { backgroundColor: color } : {}}
                >
                    {React.cloneElement(icon, { className: "w-3.5 h-3.5" })}
                </div>
                <h4 className="text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-wider">{title}</h4>
            </div>
            {rightElement && <div>{rightElement}</div>}
        </div>
    );
};

const PRESET_COLORS = [
    { name: 'Indigo', hex: '#6366f1' },
    { name: 'Esmeralda', hex: '#10b981' },
    { name: 'Âmbar', hex: '#f59e0b' },
    { name: 'Rosa', hex: '#f43f5e' },
    { name: 'Céu', hex: '#0ea5e9' },
    { name: 'Violeta', hex: '#8b5cf6' },
    { name: 'Laranja', hex: '#f97316' },
    { name: 'Ouro', hex: '#d4af37' }
];

type PendingAction = {
    type: 'execute' | 'delete' | 'update';
    record: LavagemRecord;
};

type Frequency = 'trimestral' | 'semestral' | 'anual' | 'manual';

export default function LavagemPage({ currentUser }: { currentUser: User }) {
    const [packages, setPackages] = useState<LavagemPackage[]>([]);
    const [clients, setClients] = useState<LavagemClient[]>([]);
    const [records, setRecords] = useState<LavagemRecord[]>([]);
    const [contracts, setContracts] = useState<LavagemContract[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingCep, setIsLoadingCep] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Modais
    const [isClientModalOpen, setIsClientModalOpen] = useState(false);
    const [isPackageModalOpen, setIsPackageModalOpen] = useState(false);
    const [isWashModalOpen, setIsWashModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [isLaunchServiceModalOpen, setIsLaunchServiceModalOpen] = useState(false);
    const [isEditWashDateModalOpen, setIsEditWashDateModalOpen] = useState(false);
    const [isConfirmActionModalOpen, setIsConfirmActionModalOpen] = useState(false);
    const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);

    // Estados de edição/seleção
    const [editingClient, setEditingClient] = useState<LavagemClient | null>(null);
    const [editingPackage, setEditingPackage] = useState<LavagemPackage | null>(null);
    const [selectedClientForModal, setSelectedClientForModal] = useState<LavagemClient | null>(null);
    const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
    const [isClientLocked, setIsClientLocked] = useState(false);
    const [modalMessage, setModalMessage] = useState('');

    // Abas e Filtros
    const [activeTab, setActiveTab] = useState<'timeline' | 'oportunidades'>('timeline');
    const [filterStatus, setFilterStatus] = useState('Todos');
    const [usePeriodFilter, setUsePeriodFilter] = useState(false);
    const [periodStart, setPeriodStart] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]); 
    const [periodEnd, setPeriodEnd] = useState(new Date().toISOString().split('T')[0]);

    // Formulários
    const [clientForm, setClientForm] = useState<Partial<LavagemClient>>({
        name: '', phone: '', cep: '', address: '', address_number: '', complement: '', city: '', plates_count: 0, installation_end_date: '', observations: ''
    });
    const [packageForm, setPackageForm] = useState({
        name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0
    });
    const [scheduleDates, setScheduleDates] = useState<string[]>([]);
    const [frequency, setFrequency] = useState<Frequency>('semestral');
    const [launchServiceForm, setLaunchServiceForm] = useState({ 
        clientId: '', 
        packageId: '',
        installationEndDate: new Date().toISOString().split('T')[0],
        travelCost: 0
    });
    const [editWashValue, setEditWashValue] = useState<{ date: string, status: 'scheduled' | 'executed' | 'cancelled' }>({ date: '', status: 'scheduled' });

    const lastFetchedCep = useRef('');

    const loadData = async () => {
        setIsLoading(true);
        try {
            const isAdmin = String(currentUser.profileId) === '001';
            const [pkgData, cliData, recData, contractData] = await Promise.all([
                dataService.getAll<LavagemPackage>('lavagem_packages', currentUser.id, isAdmin),
                dataService.getAll<LavagemClient>('lavagem_clients', currentUser.id, isAdmin),
                dataService.getAll<LavagemRecord>('lavagem_records', currentUser.id, isAdmin),
                dataService.getAll<LavagemContract>('lavagem_contracts', undefined, true) 
            ]);
            setPackages(pkgData.sort((a, b) => (a.wash_qty - b.wash_qty) || a.name.localeCompare(b.name)));
            setClients(cliData.sort((a,b) => a.name.localeCompare(b.name)));
            setRecords(recData);
            setContracts(contractData || []);
        } catch (e) { 
            console.error(e); 
        } finally { 
            setIsLoading(false); 
        }
    };

    useEffect(() => { loadData(); }, [currentUser.id]);

    // Busca CEP
    useEffect(() => {
        const cleanCep = (clientForm.cep || '').replace(/\D/g, '');
        if (cleanCep.length === 8 && isClientModalOpen && cleanCep !== lastFetchedCep.current) {
            const fetchCep = async () => {
                setIsLoadingCep(true);
                try {
                    const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
                    const data = await response.json();
                    if (!data.erro) {
                        lastFetchedCep.current = cleanCep;
                        setClientForm(prev => ({ 
                            ...prev, 
                            address: data.logradouro || prev.address, 
                            city: data.localidade || prev.city 
                        }));
                    }
                } catch (e) { console.error(e); } finally { setIsLoadingCep(false); }
            };
            fetchCep();
        }
    }, [clientForm.cep, isClientModalOpen]);

    const getClientPackageInfo = (client: LavagemClient) => {
        const pkg = packages.find(p => p.id === client.package_id);
        const clientRecords = records.filter(r => r.client_id === client.id);
        const launchDate = client.package_launch_date || '1970-01-01';
        const currentCycleRecords = clientRecords.filter(r => (r.created_at || r.date) >= launchDate);
        const executedCount = currentCycleRecords.filter(r => r.status === 'executed').length;
        const washQtyLimit = client.contract_wash_qty || pkg?.wash_qty || 0;
        const pricePerPlate = client.contract_price_per_plate || pkg?.price_per_plate || 0;
        const allScheduled = currentCycleRecords.filter(r => r.status === 'scheduled').sort((a, b) => a.date.localeCompare(b.date));
        const nextScheduled = allScheduled[0];
        const pendingToScheduleCount = Math.max(0, washQtyLimit - executedCount - allScheduled.length);

        const subtotalPlacas = pricePerPlate * (client.plates_count || 0);
        const contractTotalValue = (subtotalPlacas * washQtyLimit) + (client.travel_cost || 0);

        const lastExecutedWash = clientRecords
            .filter(r => r.status === 'executed')
            .sort((a, b) => b.date.localeCompare(a.date))[0];

        const lastEventDate = lastExecutedWash?.date || client.installation_end_date;
        let daysSinceLastEvent = 0;
        let isHighOpportunity = false;
        let isModerateOpportunity = false;

        if (lastEventDate) {
            const dateObj = new Date(lastEventDate);
            const today = new Date();
            const diffTime = Math.abs(today.getTime() - dateObj.getTime());
            daysSinceLastEvent = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            isModerateOpportunity = daysSinceLastEvent >= 180;
            isHighOpportunity = daysSinceLastEvent >= 330;
        }

        const totalAccumulated = contracts
            .filter(c => c.client_id === client.id)
            .reduce((acc, c) => acc + Number(c.total_value), 0);

        return { 
            pkg, 
            executedCount, 
            washQtyLimit, 
            nextScheduled, 
            allScheduled, 
            currentCycleRecords, 
            pendingToScheduleCount, 
            contractTotalValue, 
            pricePerPlate,
            totalAccumulated,
            travelCost: client.travel_cost || 0,
            isHighOpportunity,
            isModerateOpportunity,
            daysSinceLastEvent,
            lastEventDate,
            hasNeverWashed: !lastExecutedWash
        };
    };

    const visibleClientsWithInfo = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];

        return clients.map(client => ({
            client,
            info: getClientPackageInfo(client)
        })).filter(({ client, info }) => {
            if (activeTab === 'oportunidades' && client.package_id) return false;
            if (activeTab === 'timeline' && !client.package_id) return false;
            if (searchTerm && !client.name.toLowerCase().includes(searchTerm.toLowerCase()) && !(client.city || '').toLowerCase().includes(searchTerm.toLowerCase())) return false;

            if (activeTab === 'timeline') {
                const isFinished = info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0;
                const hasOverdue = info.allScheduled.some(r => r.date < todayStr);

                if (filterStatus !== 'Todos') {
                    if (filterStatus === 'Atrasados' && !hasOverdue) return false;
                    if (filterStatus === 'Ciclo Finalizado' && !isFinished) return false;
                    if (filterStatus === 'Com agendamentos' && info.allScheduled.length === 0) return false;
                    if (filterStatus === 'Sem Agendamento' && info.pendingToScheduleCount === 0) return false;
                }

                if (usePeriodFilter) {
                    const scheduledInPeriod = info.allScheduled.some(r => r.date >= periodStart && r.date <= periodEnd);
                    const executedInPeriod = info.currentCycleRecords.some(r => r.status === 'executed' && r.date >= periodStart && r.date <= periodEnd);
                    const launchInPeriod = client.package_launch_date && client.package_launch_date.split('T')[0] >= periodStart && client.package_launch_date.split('T')[0] <= periodEnd;
                    if (!scheduledInPeriod && !executedInPeriod && !launchInPeriod) return false;
                }
            }
            return true;
        });
    }, [clients, packages, records, contracts, activeTab, searchTerm, filterStatus, usePeriodFilter, periodStart, periodEnd]);

    const handleSaveClient = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemClient = {
                id: editingClient ? editingClient.id : `wash-cli-${Date.now()}`,
                owner_id: currentUser.id,
                name: clientForm.name!,
                phone: clientForm.phone,
                cep: clientForm.cep!,
                address: clientForm.address!,
                address_number: clientForm.address_number!,
                complement: clientForm.complement!,
                city: clientForm.city!,
                plates_count: clientForm.plates_count!,
                observations: clientForm.observations,
                installation_end_date: clientForm.installation_end_date || undefined,
                package_id: editingClient?.package_id,
                contract_wash_qty: editingClient?.contract_wash_qty,
                contract_price_per_plate: editingClient?.contract_price_per_plate,
                package_launch_date: editingClient?.package_launch_date,
                travel_cost: editingClient?.travel_cost
            };
            await dataService.save('lavagem_clients', data);
            setIsClientModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleSavePackage = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemPackage = {
                id: editingPackage ? editingPackage.id : `wash-pkg-${Date.now()}`,
                owner_id: currentUser.id,
                name: packageForm.name,
                color: packageForm.color,
                wash_qty: packageForm.wash_qty,
                price_per_plate: packageForm.price_per_plate
            };
            await dataService.save('lavagem_packages', data);
            setEditingPackage(null);
            setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 });
            await loadData();
        } finally { setIsSaving(false); }
    };

    // Fix: Added handleEditPackage function to allow editing wash plans
    const handleEditPackage = (pkg: LavagemPackage) => {
        setEditingPackage(pkg);
        setPackageForm({
            name: pkg.name,
            color: pkg.color,
            wash_qty: pkg.wash_qty,
            price_per_plate: pkg.price_per_plate
        });
    };

    const handleOpenLaunchModal = (clientId: string = '') => {
        const client = clients.find(c => c.id === clientId);
        setLaunchServiceForm({ 
            clientId, 
            packageId: '', 
            installationEndDate: client?.installation_end_date || new Date().toISOString().split('T')[0],
            travelCost: 0
        });
        setIsClientLocked(!!clientId);
        setIsLaunchServiceModalOpen(true);
    };

    const handleLaunchService = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!launchServiceForm.clientId || !launchServiceForm.packageId) return;
        const client = clients.find(c => c.id === launchServiceForm.clientId);
        const selectedPkg = packages.find(p => p.id === launchServiceForm.packageId);
        if (!client || !selectedPkg) return;

        setIsSaving(true);
        try {
            const launchDate = new Date();
            const platesTotal = selectedPkg.price_per_plate * (client.plates_count || 0);
            const contractTotal = (platesTotal * selectedPkg.wash_qty) + Number(launchServiceForm.travelCost || 0);

            await dataService.save('lavagem_clients', {
                ...client,
                package_id: selectedPkg.id,
                contract_price_per_plate: selectedPkg.price_per_plate,
                contract_wash_qty: selectedPkg.wash_qty,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                package_launch_date: launchDate.toISOString()
            });

            await dataService.save('lavagem_contracts', {
                id: `cont-${Date.now()}`,
                client_id: client.id,
                package_name: selectedPkg.name,
                total_value: contractTotal,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                created_at: launchDate.toISOString()
            });

            await loadData();
            setIsLaunchServiceModalOpen(false);
            setModalMessage("Plano vinculado com sucesso!");
            setSuccessModalOpen(true);
        } finally { setIsSaving(false); }
    };

    const executePendingAction = async () => {
        if (!pendingAction) return;
        setIsSaving(true);
        try {
            if (pendingAction.type === 'execute') await dataService.save('lavagem_records', { ...pendingAction.record, status: 'executed' });
            else if (pendingAction.type === 'delete') await dataService.delete('lavagem_records', pendingAction.record.id);
            else if (pendingAction.type === 'update') await dataService.save('lavagem_records', { ...pendingAction.record, date: editWashValue.date, status: editWashValue.status });
            await loadData();
            setIsConfirmActionModalOpen(false);
            setIsEditWashDateModalOpen(false);
            setPendingAction(null);
        } finally { setIsSaving(false); }
    };

    if (isLoading) return <div className="flex justify-center p-20"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-cyan-600"></div></div>;

    const inputClass = "w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 p-2.5 text-xs font-bold text-gray-800 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all shadow-sm";

    const timelineGroups = useMemo(() => {
        if (activeTab !== 'timeline') return [];
        const groups: Record<string, { label: string, items: any[] }> = {
            'pending': { label: 'Ação necessária / Ciclos pendentes', items: [] }
        };
        visibleClientsWithInfo.forEach(item => {
            const nextDate = item.info.nextScheduled?.date || null;
            if (nextDate) {
                const date = new Date(nextDate);
                const key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
                const label = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                if (!groups[key]) groups[key] = { label: toSentenceCase(label), items: [] };
                groups[key].items.push(item);
            } else {
                groups['pending'].items.push(item);
            }
        });
        return Object.keys(groups).sort((a, b) => a === 'pending' ? -1 : a.localeCompare(b)).map(k => ({ key: k, ...groups[k] })).filter(g => g.items.length > 0);
    }, [visibleClientsWithInfo, activeTab]);

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <header className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-6">
                <div className="flex items-center gap-5 flex-1">
                    <div className="p-4 bg-cyan-600 text-white rounded-2xl shadow-lg shadow-cyan-600/20"><SparklesIcon className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Gestão de Lavagens</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1">Recorrência solar inteligente</p>
                    </div>
                </div>
                <div className="flex flex-wrap justify-center gap-3">
                    <button onClick={() => setIsPackageModalOpen(true)} className="flex items-center gap-2 px-5 py-2.5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Planos</button>
                    <button onClick={() => { setEditingClient(null); setClientForm({name:'', phone:'', cep:'', address:'', address_number:'', complement:'', city:'', plates_count:0, installation_end_date: '', observations: ''}); setIsClientModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Novo cliente</button>
                    <button onClick={() => handleOpenLaunchModal()} className="flex items-center gap-2 px-8 py-2.5 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-xl shadow-cyan-600/20 hover:bg-cyan-700 transition-all active:scale-95">Lançar serviço</button>
                </div>
            </header>

            <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                <button onClick={() => setActiveTab('timeline')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'timeline' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><CalendarIcon className="w-4 h-4" /> Timeline de Serviços</button>
                <button onClick={() => setActiveTab('oportunidades')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'oportunidades' ? 'bg-amber-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><TrendUpIcon className="w-4 h-4" /> Oportunidades</button>
            </div>

            {activeTab === 'timeline' ? (
                <div className="space-y-10">
                    {timelineGroups.map(group => (
                        <section key={group.key}>
                            <div className="flex items-center gap-4 mb-6">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white shadow-md ${group.key === 'pending' ? 'bg-slate-500' : 'bg-cyan-600'}`}>
                                    {group.key === 'pending' ? <ClockIcon className="w-6 h-6" /> : <CalendarIcon className="w-6 h-6" />}
                                </div>
                                <h3 className="text-lg font-black text-gray-800 dark:text-white">{group.label}</h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {group.items.map(({ client, info }) => {
                                    const packageColor = info.pkg?.color || '#94a3b8';
                                    const isHighlight = group.key === 'pending' && (info.isModerateOpportunity || info.isHighOpportunity);

                                    return (
                                        <div 
                                            key={client.id} 
                                            className={`bg-white dark:bg-gray-800 rounded-3xl border p-5 shadow-sm hover:shadow-xl transition-all flex flex-col relative ${isHighlight ? 'border-amber-400 ring-4 ring-amber-500/5' : 'border-gray-100 dark:border-gray-700'}`}
                                        >
                                            <div className="flex justify-between items-start mb-4">
                                                <div>
                                                    <h4 className="font-black text-gray-800 dark:text-white text-base">{client.name}</h4>
                                                    <p className="text-[10px] text-gray-400 font-bold flex items-center gap-1"><MapPinIcon className="w-3 h-3" /> {client.city}</p>
                                                </div>
                                                <button onClick={() => { setEditingClient(client); setClientForm({...client, installation_end_date: client.installation_end_date || ''}); setIsClientModalOpen(true); }} className="p-1.5 text-gray-300 hover:text-cyan-600"><EditIcon className="w-4 h-4" /></button>
                                            </div>

                                            <div className="bg-gray-50 dark:bg-gray-900/40 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 mb-4">
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-[9px] font-black text-gray-400 uppercase">{info.hasNeverWashed ? 'Desde Instalação' : 'Última Lavagem'}</span>
                                                    <span className={`text-[10px] font-black ${info.daysSinceLastEvent > 180 ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                </div>
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                                                    <ClockIcon className="w-3.5 h-3.5 text-gray-400" />
                                                    {info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : 'Sem registro'}
                                                </p>
                                            </div>

                                            {info.allScheduled.length > 0 ? (
                                                <div style={{ backgroundColor: packageColor }} className="rounded-2xl p-3 text-white">
                                                    <p className="text-[9px] font-black opacity-80 mb-2">Próximo Agendamento</p>
                                                    <div className="flex justify-between items-center bg-white/10 p-2 rounded-xl">
                                                        <span className="text-xs font-black">{new Date(info.nextScheduled.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</span>
                                                        <div className="flex gap-1">
                                                            <button onClick={() => { setPendingAction({ type: 'execute', record: info.nextScheduled }); setIsConfirmActionModalOpen(true); }} className="p-1 bg-white text-indigo-600 rounded-lg shadow-sm"><CheckCircleIcon className="w-4 h-4" /></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className={`p-4 rounded-2xl border-2 border-dashed text-center ${isHighlight ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
                                                    <p className="text-[10px] font-black text-gray-500 mb-3">{isHighlight ? 'Sugerir Nova Lavagem' : 'Sem agendamentos'}</p>
                                                    <button onClick={() => handleOpenLaunchModal(client.id)} className={`w-full py-2 rounded-xl font-black text-[10px] uppercase shadow-md ${isHighlight ? 'bg-amber-500 text-white' : 'bg-slate-500 text-white'}`}>
                                                        {info.executedCount >= info.washQtyLimit ? 'Renovar Plano' : 'Lançar Novo Ciclo'}
                                                    </button>
                                                </div>
                                            )}

                                            <button onClick={() => { setSelectedClientForModal(client); setIsHistoryModalOpen(true); }} className="mt-4 w-full py-2 text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 rounded-xl hover:bg-gray-50 flex items-center justify-center gap-1.5">
                                                <ClipboardListIcon className="w-3 h-3" /> Histórico Completo
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        </section>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {visibleClientsWithInfo.map(({ client, info }) => (
                        <div key={client.id} className="bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 p-5 shadow-sm hover:shadow-xl transition-all flex flex-col">
                            <h4 className="font-black text-gray-800 dark:text-white mb-1">{client.name}</h4>
                            <p className="text-[10px] text-gray-400 font-bold mb-4">{client.city}</p>
                            <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-xl mb-4 text-center">
                                <span className="text-[9px] font-bold text-gray-400 block mb-1">Potencial</span>
                                <span className="text-xl font-black text-gray-700 dark:text-white">{client.plates_count} Placas</span>
                            </div>
                            <button onClick={() => handleOpenLaunchModal(client.id)} className="w-full py-3 bg-amber-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-amber-500/20">Lançar Plano</button>
                        </div>
                    ))}
                </div>
            )}

            {/* Modais de Formulário */}
            {isClientModalOpen && (
                <Modal title={editingClient ? "Editar Cliente" : "Novo Cliente Solar"} onClose={() => setIsClientModalOpen(false)} maxWidth="max-w-2xl">
                    <form onSubmit={handleSaveClient} className="space-y-4 pt-2">
                        <SectionHeader icon={<UsersIcon />} title="Identificação" />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><FormLabel>Nome Completo</FormLabel><input required value={clientForm.name} onChange={e => setClientForm({...clientForm, name: e.target.value})} className={inputClass} /></div>
                            <div><FormLabel>WhatsApp</FormLabel><input value={clientForm.phone} onChange={e => setClientForm({...clientForm, phone: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<MapPinIcon />} title="Endereço" color="bg-teal-600" />
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="col-span-1"><FormLabel>CEP</FormLabel><input value={clientForm.cep} onChange={e => setClientForm({...clientForm, cep: e.target.value})} className={inputClass} /></div>
                            <div className="col-span-2 md:col-span-3"><FormLabel>Logradouro</FormLabel><input value={clientForm.address} onChange={e => setClientForm({...clientForm, address: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<BoltIcon />} title="Projeto" color="bg-amber-600" />
                        <div className="grid grid-cols-2 gap-4">
                            <div><FormLabel>Qtd Placas</FormLabel><input type="number" value={clientForm.plates_count} onChange={e => setClientForm({...clientForm, plates_count: parseInt(e.target.value)||0})} className={inputClass} /></div>
                            <div><FormLabel>Data Instalação</FormLabel><input type="date" value={clientForm.installation_end_date} onChange={e => setClientForm({...clientForm, installation_end_date: e.target.value})} className={inputClass} /></div>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsClientModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-black text-xs shadow-lg">Salvar Cadastro</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isPackageModalOpen && (
                <Modal title="Planos de Lavagem" onClose={() => setIsPackageModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-3">
                            <h4 className="text-[10px] font-black text-gray-400 uppercase border-b pb-2">Ativos</h4>
                            <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
                                {packages.map(pkg => (
                                    <div key={pkg.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: pkg.color }}></div>
                                            <span className="text-xs font-black text-gray-800 dark:text-white">{pkg.name}</span>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => handleEditPackage(pkg)} className="p-1 text-gray-400 hover:text-indigo-600"><EditIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <form onSubmit={handleSavePackage} className="space-y-4 bg-gray-50 dark:bg-gray-800/40 p-4 rounded-2xl border">
                            <h4 className="text-[10px] font-black text-indigo-600 uppercase">{editingPackage ? 'Editar' : 'Novo'}</h4>
                            <div><FormLabel>Nome do Plano</FormLabel><input required value={packageForm.name} onChange={e => setPackageForm({...packageForm, name: e.target.value})} className={inputClass} /></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><FormLabel>Visitas</FormLabel><input type="number" required value={packageForm.wash_qty} onChange={e => setPackageForm({...packageForm, wash_qty: parseInt(e.target.value)||1})} className={inputClass} /></div>
                                <div><FormLabel>Preço/Placa</FormLabel><input type="number" step="0.01" value={packageForm.price_per_plate} onChange={e => setPackageForm({...packageForm, price_per_plate: parseFloat(e.target.value)||0})} className={inputClass} /></div>
                            </div>
                            <button type="submit" className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-xs">Salvar Plano</button>
                        </form>
                    </div>
                </Modal>
            )}

            {isLaunchServiceModalOpen && (
                <Modal title="Lançar Ciclo de Serviço" onClose={() => setIsLaunchServiceModalOpen(false)} maxWidth="max-w-md">
                    <form onSubmit={handleLaunchService} className="space-y-5 pt-2">
                        <div>
                            <FormLabel>Cliente</FormLabel>
                            <select required disabled={isClientLocked} value={launchServiceForm.clientId} onChange={e => setLaunchServiceForm({...launchServiceForm, clientId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <FormLabel>Plano de Lavagens</FormLabel>
                            <select required value={launchServiceForm.packageId} onChange={e => setLaunchServiceForm({...launchServiceForm, packageId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {packages.map(p => <option key={p.id} value={p.id}>{p.name} ({p.wash_qty}x)</option>)}
                            </select>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsLaunchServiceModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" className="flex-[2] py-3 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-lg">Confirmar Lançamento</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isHistoryModalOpen && selectedClientForModal && (
                <Modal title={`Histórico: ${selectedClientForModal.name}`} onClose={() => setIsHistoryModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="space-y-4 pt-1">
                        <div className="max-h-[400px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
                            {records.filter(r => r.client_id === selectedClientForModal.id).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                                <div key={record.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border border-gray-100 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${record.status === 'executed' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                            {record.status === 'executed' ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                        </div>
                                        <div>
                                            <p className="text-xs font-black text-gray-800 dark:text-white">Lavagem em {new Date(record.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</p>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase">{record.status === 'executed' ? 'Concluída' : 'Agendada'}</p>
                                        </div>
                                    </div>
                                    <button onClick={async () => { if(confirm('Remover registro?')) { await dataService.delete('lavagem_records', record.id); loadData(); } }} className="p-2 text-gray-300 hover:text-red-500"><TrashIcon className="w-5 h-5" /></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </Modal>
            )}

            {isConfirmActionModalOpen && pendingAction && (
                <Modal title="Confirmar" onClose={() => setIsConfirmActionModalOpen(false)} maxWidth="max-w-sm">
                    <div className="text-center p-4 space-y-6">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-indigo-50 text-indigo-600"><CheckCircleIcon className="w-10 h-10" /></div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Marcar como concluída?</h3>
                        <div className="flex gap-4">
                            <button onClick={() => setIsConfirmActionModalOpen(false)} className="flex-1 py-3 bg-gray-100 rounded-xl font-bold text-sm">Não</button>
                            <button onClick={executePendingAction} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg">Sim, confirmar</button>
                        </div>
                    </div>
                </Modal>
            )}

            {isSuccessModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 animate-fade-in">
                    <div className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-2xl max-w-sm w-full text-center space-y-6">
                        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto animate-bounce"><CheckCircleIcon className="w-12 h-12" /></div>
                        <h3 className="text-xl font-black text-gray-800 dark:text-white">Concluído!</h3>
                        <p className="text-sm text-gray-500 font-bold">{modalMessage}</p>
                        <button onClick={() => setSuccessModalOpen(false)} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest">Entendido</button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
    SparklesIcon, PlusIcon, TrashIcon, EditIcon, 
    CalendarIcon, MapIcon, BoltIcon, CheckCircleIcon, 
    XCircleIcon, SearchIcon, ClockIcon, DollarIcon,
    ChevronDownIcon, HomeIcon, MapPinIcon, UsersIcon, ClipboardListIcon,
    ExclamationTriangleIcon, FilterIcon, ArrowLeftIcon, TrendUpIcon, StarIcon,
    DocumentReportIcon, PhoneIcon
} from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { dataService } from '../services/dataService';
import type { User, LavagemPackage, LavagemClient, LavagemRecord, FinancialCategory, LavagemContract } from '../types';

const toSentenceCase = (str: string) => {
    if (!str) return '';
    const clean = str.toLowerCase();
    return clean.charAt(0).toUpperCase() + clean.slice(1);
};

const formatCurrency = (value: number) => {
    if (value === undefined || value === null || isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const FormLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="block text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-1 ml-0.5 tracking-tight">{children}</label>
);

const SectionHeader: React.FC<{ icon: React.ReactElement<any>; title: string; color?: string; rightElement?: React.ReactNode }> = ({ icon, title, color = "bg-indigo-600", rightElement }) => {
    const isHex = color.startsWith('#');
    return (
        <div className="flex items-center justify-between mb-3 pb-1 border-b border-gray-100 dark:border-gray-700/50">
            <div className="flex items-center gap-2">
                <div 
                    className={`p-1 rounded-lg text-white ${!isHex ? color : ''}`}
                    style={isHex ? { backgroundColor: color } : {}}
                >
                    {React.cloneElement(icon, { className: "w-3.5 h-3.5" })}
                </div>
                <h4 className="text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-wider">{title}</h4>
            </div>
            {rightElement && <div>{rightElement}</div>}
        </div>
    );
};

const PRESET_COLORS = [
    { name: 'Indigo', hex: '#6366f1' },
    { name: 'Esmeralda', hex: '#10b981' },
    { name: 'Âmbar', hex: '#f59e0b' },
    { name: 'Rosa', hex: '#f43f5e' },
    { name: 'Céu', hex: '#0ea5e9' },
    { name: 'Violeta', hex: '#8b5cf6' },
    { name: 'Laranja', hex: '#f97316' },
    { name: 'Ouro', hex: '#d4af37' }
];

type PendingAction = {
    type: 'execute' | 'delete' | 'update';
    record: LavagemRecord;
};

type Frequency = 'trimestral' | 'semestral' | 'anual' | 'manual';

export default function LavagemPage({ currentUser }: { currentUser: User }) {
    const [packages, setPackages] = useState<LavagemPackage[]>([]);
    const [clients, setClients] = useState<LavagemClient[]>([]);
    const [records, setRecords] = useState<LavagemRecord[]>([]);
    const [contracts, setContracts] = useState<LavagemContract[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingCep, setIsLoadingCep] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);
    const [modalMessage, setModalMessage] = useState('');

    const [activeTab, setActiveTab] = useState<'timeline' | 'oportunidades'>('timeline');
    const [filterStatus, setFilterStatus] = useState('Todos');
    const [usePeriodFilter, setUsePeriodFilter] = useState(false);
    const [periodStart, setPeriodStart] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]); 
    const [periodEnd, setPeriodEnd] = useState(new Date().toISOString().split('T')[0]);

    // Estados dos Modais
    const [isClientModalOpen, setIsClientModalOpen] = useState(false);
    const [isPackageModalOpen, setIsPackageModalOpen] = useState(false);
    const [isWashModalOpen, setIsWashModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [isLaunchServiceModalOpen, setIsLaunchServiceModalOpen] = useState(false);
    const [isEditWashDateModalOpen, setIsEditWashDateModalOpen] = useState(false);
    const [isConfirmActionModalOpen, setIsConfirmActionModalOpen] = useState(false);

    const [editingClient, setEditingClient] = useState<LavagemClient | null>(null);
    const [editingPackage, setEditingPackage] = useState<LavagemPackage | null>(null);
    const [selectedClientForModal, setSelectedClientForModal] = useState<LavagemClient | null>(null);
    const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
    const [isClientLocked, setIsClientLocked] = useState(false);

    const [clientForm, setClientForm] = useState<Partial<LavagemClient>>({
        name: '', phone: '', cep: '', address: '', address_number: '', complement: '', city: '', plates_count: 0, installation_end_date: '', observations: ''
    });
    const [packageForm, setPackageForm] = useState({
        name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0
    });
    const [scheduleDates, setScheduleDates] = useState<string[]>([]);
    const [frequency, setFrequency] = useState<Frequency>('semestral');
    const [launchServiceForm, setLaunchServiceForm] = useState({ 
        clientId: '', 
        packageId: '',
        installationEndDate: new Date().toISOString().split('T')[0],
        travelCost: 0
    });
    const [editWashValue, setEditWashValue] = useState<{ date: string, status: 'scheduled' | 'executed' | 'cancelled' }>({ date: '', status: 'scheduled' });

    const lastFetchedCep = useRef('');

    const loadData = async () => {
        setIsLoading(true);
        try {
            const isAdmin = String(currentUser.profileId) === '001';
            const [pkgData, cliData, recData, contractData] = await Promise.all([
                dataService.getAll<LavagemPackage>('lavagem_packages', currentUser.id, isAdmin),
                dataService.getAll<LavagemClient>('lavagem_clients', currentUser.id, isAdmin),
                dataService.getAll<LavagemRecord>('lavagem_records', currentUser.id, isAdmin),
                dataService.getAll<LavagemContract>('lavagem_contracts', undefined, true) 
            ]);
            setPackages(pkgData.sort((a, b) => (a.wash_qty - b.wash_qty) || a.name.localeCompare(b.name)));
            setClients(cliData.sort((a,b) => a.name.localeCompare(b.name)));
            setRecords(recData);
            setContracts(contractData || []);
        } catch (e) { console.error(e); } finally { setIsLoading(false); }
    };

    useEffect(() => { loadData(); }, [currentUser.id]);

    useEffect(() => {
        const cleanCep = (clientForm.cep || '').replace(/\D/g, '');
        if (cleanCep.length === 8 && isClientModalOpen && cleanCep !== lastFetchedCep.current) {
            const fetchCep = async () => {
                setIsLoadingCep(true);
                try {
                    const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
                    const data = await response.json();
                    if (!data.erro) {
                        lastFetchedCep.current = cleanCep;
                        setClientForm(prev => ({ 
                            ...prev, 
                            address: data.logradouro || prev.address, 
                            city: data.localidade || prev.city 
                        }));
                    }
                } catch (e) { console.error(e); } finally { setIsLoadingCep(false); }
            };
            fetchCep();
        }
    }, [clientForm.cep, isClientModalOpen]);

    const getClientPackageInfo = (client: LavagemClient) => {
        const pkg = packages.find(p => p.id === client.package_id);
        const clientRecords = records.filter(r => r.client_id === client.id);
        const launchDate = client.package_launch_date || '1970-01-01';
        const currentCycleRecords = clientRecords.filter(r => (r.created_at || r.date) >= launchDate);
        const executedCount = currentCycleRecords.filter(r => r.status === 'executed').length;
        const washQtyLimit = client.contract_wash_qty || pkg?.wash_qty || 0;
        const pricePerPlate = client.contract_price_per_plate || pkg?.price_per_plate || 0;
        const allScheduled = currentCycleRecords.filter(r => r.status === 'scheduled').sort((a, b) => a.date.localeCompare(b.date));
        const nextScheduled = allScheduled[0];
        const pendingToScheduleCount = Math.max(0, washQtyLimit - executedCount - allScheduled.length);

        const subtotalPlacas = pricePerPlate * (client.plates_count || 0);
        const contractTotalValue = (subtotalPlacas * washQtyLimit) + (client.travel_cost || 0);

        const lastExecutedWash = clientRecords
            .filter(r => r.status === 'executed')
            .sort((a, b) => b.date.localeCompare(a.date))[0];

        const lastEventDate = lastExecutedWash?.date || client.installation_end_date;
        let daysSinceLastEvent = 0;
        let isHighOpportunity = false;
        let isModerateOpportunity = false;

        if (lastEventDate) {
            const dateObj = new Date(lastEventDate);
            const today = new Date();
            const diffTime = Math.abs(today.getTime() - dateObj.getTime());
            daysSinceLastEvent = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            isModerateOpportunity = daysSinceLastEvent >= 180; 
            isHighOpportunity = daysSinceLastEvent >= 330; 
        }

        const totalAccumulated = contracts
            .filter(c => c.client_id === client.id)
            .reduce((acc, c) => acc + Number(c.total_value), 0);

        return { 
            pkg, 
            executedCount, 
            washQtyLimit, 
            nextScheduled, 
            allScheduled, 
            currentCycleRecords, 
            pendingToScheduleCount, 
            contractTotalValue, 
            pricePerPlate,
            totalAccumulated,
            travelCost: client.travel_cost || 0,
            isHighOpportunity,
            isModerateOpportunity,
            daysSinceLastEvent,
            lastEventDate,
            hasNeverWashed: !lastExecutedWash
        };
    };

    const visibleClientsWithInfo = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];

        return clients.map(client => ({
            client,
            info: getClientPackageInfo(client)
        })).filter(({ client, info }) => {
            if (activeTab === 'oportunidades' && client.package_id) return false;
            if (activeTab === 'timeline' && !client.package_id) return false;
            if (searchTerm && !client.name.toLowerCase().includes(searchTerm.toLowerCase()) && !(client.city || '').toLowerCase().includes(searchTerm.toLowerCase())) return false;

            if (activeTab === 'timeline') {
                const isFinished = info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0;
                const hasOverdue = info.allScheduled.some(r => r.date < todayStr);

                if (filterStatus !== 'Todos') {
                    if (filterStatus === 'Atrasados' && !hasOverdue) return false;
                    if (filterStatus === 'Ciclo Finalizado' && !isFinished) return false;
                    if (filterStatus === 'Com agendamentos' && info.allScheduled.length === 0) return false;
                    if (filterStatus === 'Sem Agendamento' && info.pendingToScheduleCount === 0) return false;
                }

                if (usePeriodFilter) {
                    const scheduledInPeriod = info.allScheduled.some(r => r.date >= periodStart && r.date <= periodEnd);
                    const executedInPeriod = info.currentCycleRecords.some(r => r.status === 'executed' && r.date >= periodStart && r.date <= periodEnd);
                    const launchInPeriod = client.package_launch_date && client.package_launch_date.split('T')[0] >= periodStart && client.package_launch_date.split('T')[0] <= periodEnd;
                    if (!scheduledInPeriod && !executedInPeriod && !launchInPeriod) return false;
                }
            }
            return true;
        });
    }, [clients, packages, records, contracts, activeTab, searchTerm, filterStatus, usePeriodFilter, periodStart, periodEnd]);

    const handleSaveClient = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemClient = {
                id: editingClient ? editingClient.id : `wash-cli-${Date.now()}`,
                owner_id: currentUser.id,
                name: clientForm.name!,
                phone: clientForm.phone,
                cep: clientForm.cep!,
                address: clientForm.address!,
                address_number: clientForm.address_number!,
                complement: clientForm.complement!,
                city: clientForm.city!,
                plates_count: clientForm.plates_count!,
                observations: clientForm.observations,
                installation_end_date: clientForm.installation_end_date || undefined,
                package_id: editingClient?.package_id,
                contract_wash_qty: editingClient?.contract_wash_qty,
                contract_price_per_plate: editingClient?.contract_price_per_plate,
                package_launch_date: editingClient?.package_launch_date,
                travel_cost: editingClient?.travel_cost
            };
            await dataService.save('lavagem_clients', data);
            setIsClientModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleSavePackage = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemPackage = {
                id: editingPackage ? editingPackage.id : `wash-pkg-${Date.now()}`,
                owner_id: currentUser.id,
                name: packageForm.name,
                color: packageForm.color,
                wash_qty: packageForm.wash_qty,
                price_per_plate: packageForm.price_per_plate
            };
            await dataService.save('lavagem_packages', data);
            setEditingPackage(null);
            setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 });
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleEditPackage = (pkg: LavagemPackage) => {
        setEditingPackage(pkg);
        setPackageForm({
            name: pkg.name,
            color: pkg.color,
            wash_qty: pkg.wash_qty,
            price_per_plate: pkg.price_per_plate
        });
    };

    const handleDeletePackage = async (id: string) => {
        const inUse = clients.some(c => c.package_id === id);
        if (inUse) { alert("Não é possível excluir este plano pois existem clientes vinculados a ele."); return; }
        if (confirm("Deseja realmente remover este plano?")) {
            setIsSaving(true);
            try { await dataService.delete('lavagem_packages', id); await loadData(); } finally { setIsSaving(false); }
        }
    };

    const handleOpenLaunchModal = (clientId: string = '') => {
        const client = clients.find(c => c.id === clientId);
        setLaunchServiceForm({ 
            clientId, 
            packageId: '', 
            installationEndDate: client?.installation_end_date || new Date().toISOString().split('T')[0],
            travelCost: client?.travel_cost || 0
        });
        setIsClientLocked(!!clientId);
        setIsLaunchServiceModalOpen(true);
    };

    const handleLaunchService = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!launchServiceForm.clientId || !launchServiceForm.packageId) return;
        const client = clients.find(c => c.id === launchServiceForm.clientId);
        const selectedPkg = packages.find(p => p.id === launchServiceForm.packageId);
        if (!client || !selectedPkg) return;

        setIsSaving(true);
        try {
            const launchDate = new Date();
            const platesTotal = selectedPkg.price_per_plate * (client.plates_count || 0);
            const contractTotal = (platesTotal * selectedPkg.wash_qty) + Number(launchServiceForm.travelCost || 0);

            await dataService.save('lavagem_clients', {
                ...client,
                package_id: selectedPkg.id,
                contract_price_per_plate: selectedPkg.price_per_plate,
                contract_wash_qty: selectedPkg.wash_qty,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                package_launch_date: launchDate.toISOString()
            });

            await dataService.save('lavagem_contracts', {
                id: `cont-${Date.now()}`,
                client_id: client.id,
                package_name: selectedPkg.name,
                total_value: contractTotal,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                created_at: launchDate.toISOString()
            });

            await loadData();
            setIsLaunchServiceModalOpen(false);
            setModalMessage("Plano vinculado com sucesso!");
            setSuccessModalOpen(true);
        } finally { setIsSaving(false); }
    };

    const executePendingAction = async () => {
        if (!pendingAction) return;
        setIsSaving(true);
        try {
            if (pendingAction.type === 'execute') await dataService.save('lavagem_records', { ...pendingAction.record, status: 'executed' });
            else if (pendingAction.type === 'delete') await dataService.delete('lavagem_records', pendingAction.record.id);
            else if (pendingAction.type === 'update') await dataService.save('lavagem_records', { ...pendingAction.record, date: editWashValue.date, status: editWashValue.status });
            await loadData();
            setIsConfirmActionModalOpen(false);
            setIsEditWashDateModalOpen(false);
            setPendingAction(null);
        } finally { setIsSaving(false); }
    };

    const timelineGroups = useMemo(() => {
        if (activeTab !== 'timeline') return [];
        const groups: Record<string, { label: string, items: any[] }> = {
            'pending': { label: 'Ação necessária / Ciclos pendentes', items: [] }
        };
        visibleClientsWithInfo.forEach(item => {
            const nextDate = item.info.nextScheduled?.date || null;
            if (nextDate) {
                const date = new Date(nextDate);
                const key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
                const label = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                if (!groups[key]) groups[key] = { label: toSentenceCase(label), items: [] };
                groups[key].items.push(item);
            } else {
                groups['pending'].items.push(item);
            }
        });
        return Object.keys(groups).sort((a, b) => a === 'pending' ? -1 : a.localeCompare(b)).map(k => ({ key: k, ...groups[k] })).filter(g => g.items.length > 0);
    }, [visibleClientsWithInfo, activeTab]);

    if (isLoading) return <div className="flex justify-center p-20"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-cyan-600"></div></div>;

    const inputClass = "w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 p-2.5 text-xs font-bold text-gray-800 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all shadow-sm";

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <header className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-6">
                <div className="flex items-center gap-5 flex-1">
                    <div className="p-4 bg-cyan-600 text-white rounded-2xl shadow-lg shadow-cyan-600/20"><SparklesIcon className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Gestão de Lavagens</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1">Recorrência solar inteligente</p>
                    </div>
                </div>
                <div className="flex flex-wrap justify-center gap-3">
                    <button onClick={() => setIsPackageModalOpen(true)} className="flex items-center gap-2 px-5 py-2.5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Planos</button>
                    <button onClick={() => { setEditingClient(null); setClientForm({name:'', phone:'', cep:'', address:'', address_number:'', complement:'', city:'', plates_count:0, installation_end_date: '', observations: ''}); setIsClientModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Novo cliente</button>
                    <button onClick={() => handleOpenLaunchModal()} className="flex items-center gap-2 px-8 py-2.5 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-xl shadow-cyan-600/20 hover:bg-cyan-700 transition-all active:scale-95">Lançar serviço</button>
                </div>
            </header>

            <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                <button onClick={() => setActiveTab('timeline')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'timeline' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><CalendarIcon className="w-4 h-4" /> Timeline de Serviços</button>
                <button onClick={() => setActiveTab('oportunidades')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'oportunidades' ? 'bg-amber-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><TrendUpIcon className="w-4 h-4" /> Oportunidades</button>
            </div>

            {activeTab === 'timeline' ? (
                <div className="space-y-10">
                    {timelineGroups.map(group => (
                        <section key={group.key}>
                            <div className="flex items-center gap-4 mb-6">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white shadow-md ${group.key === 'pending' ? 'bg-slate-500' : 'bg-cyan-600'}`}>
                                    {group.key === 'pending' ? <ClockIcon className="w-6 h-6" /> : <CalendarIcon className="w-6 h-6" />}
                                </div>
                                <h3 className="text-lg font-black text-gray-800 dark:text-white">{group.label}</h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {group.items.map(({ client, info }) => {
                                    const packageColor = info.pkg?.color || '#94a3b8';
                                    const isHighlight = group.key === 'pending' && (info.isModerateOpportunity || info.isHighOpportunity);

                                    return (
                                        <div 
                                            key={client.id} 
                                            className={`bg-white dark:bg-gray-800 rounded-3xl border p-5 shadow-sm hover:shadow-xl transition-all flex flex-col relative ${isHighlight ? 'border-amber-400 ring-4 ring-amber-500/5' : 'border-gray-100 dark:border-gray-700'}`}
                                        >
                                            <div className="flex justify-between items-start mb-4">
                                                <div>
                                                    <h4 className="font-black text-gray-800 dark:text-white text-base leading-tight">{client.name}</h4>
                                                    <p className="text-[10px] text-gray-400 font-bold flex items-center gap-1"><MapPinIcon className="w-3 h-3" /> {client.city || 'S/ local'}</p>
                                                </div>
                                                <button onClick={() => { setEditingClient(client); setClientForm({...client, installation_end_date: client.installation_end_date || ''}); setIsClientModalOpen(true); }} className="p-1.5 text-gray-300 hover:text-cyan-600"><EditIcon className="w-4 h-4" /></button>
                                            </div>

                                            <div className="bg-gray-50 dark:bg-gray-900/40 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 mb-4">
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-[9px] font-black text-gray-400 uppercase">{info.hasNeverWashed ? 'Desde Instalação' : 'Última Lavagem'}</span>
                                                    <span className={`text-[10px] font-black ${info.daysSinceLastEvent > 180 ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                </div>
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                                                    <ClockIcon className="w-3.5 h-3.5 text-gray-400" />
                                                    {info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : 'Sem registro'}
                                                </p>
                                            </div>

                                            {info.allScheduled.length > 0 ? (
                                                <div style={{ backgroundColor: packageColor }} className="rounded-2xl p-3 text-white">
                                                    <p className="text-[9px] font-black opacity-80 mb-2">Próximo Agendamento</p>
                                                    <div className="flex justify-between items-center bg-white/10 p-2 rounded-xl">
                                                        <span className="text-xs font-black">{new Date(info.nextScheduled.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</span>
                                                        <div className="flex gap-1">
                                                            <button onClick={() => { setPendingAction({ type: 'execute', record: info.nextScheduled }); setIsConfirmActionModalOpen(true); }} className="p-1 bg-white text-indigo-600 rounded-lg shadow-sm"><CheckCircleIcon className="w-4 h-4" /></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className={`p-4 rounded-2xl border-2 border-dashed text-center ${isHighlight ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
                                                    <p className="text-[10px] font-black text-gray-500 mb-3">{isHighlight ? 'Sugerir Nova Lavagem' : 'Sem agendamentos'}</p>
                                                    <button onClick={() => handleOpenLaunchModal(client.id)} className={`w-full py-2 rounded-xl font-black text-[10px] uppercase shadow-md ${isHighlight ? 'bg-amber-500 text-white' : 'bg-slate-500 text-white'}`}>
                                                        {info.executedCount >= info.washQtyLimit ? 'Renovar Plano' : 'Lançar Novo Ciclo'}
                                                    </button>
                                                </div>
                                            )}

                                            <button onClick={() => { setSelectedClientForModal(client); setIsHistoryModalOpen(true); }} className="mt-4 w-full py-2 text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 rounded-xl hover:bg-gray-50 flex items-center justify-center gap-1.5">
                                                <ClipboardListIcon className="w-3 h-3" /> Histórico Completo
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        </section>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {visibleClientsWithInfo.map(({ client, info }) => (
                        <div key={client.id} className="bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 p-5 shadow-sm hover:shadow-xl transition-all flex flex-col">
                            <h4 className="font-black text-gray-800 dark:text-white mb-1">{client.name}</h4>
                            <p className="text-[10px] text-gray-400 font-bold mb-4">{client.city || 'S/ local'}</p>
                            <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-xl mb-4 text-center">
                                <span className="text-[9px] font-bold text-gray-400 block mb-1">Potencial</span>
                                <span className="text-xl font-black text-gray-700 dark:text-white">{client.plates_count} Placas</span>
                            </div>
                            <button onClick={() => handleOpenLaunchModal(client.id)} className="w-full py-3 bg-amber-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-amber-500/20">Lançar Plano</button>
                        </div>
                    ))}
                </div>
            )}

            {/* Modais de Formulário */}
            {isClientModalOpen && (
                <Modal title={editingClient ? "Editar Cliente" : "Novo Cliente Solar"} onClose={() => setIsClientModalOpen(false)} maxWidth="max-w-2xl">
                    <form onSubmit={handleSaveClient} className="space-y-4 pt-2">
                        <SectionHeader icon={<UsersIcon />} title="Identificação" />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><FormLabel>Nome Completo</FormLabel><input required value={clientForm.name} onChange={e => setClientForm({...clientForm, name: e.target.value})} className={inputClass} /></div>
                            <div><FormLabel>WhatsApp</FormLabel><input value={clientForm.phone} onChange={e => setClientForm({...clientForm, phone: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<MapPinIcon />} title="Endereço" color="bg-teal-600" />
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="col-span-1"><FormLabel>CEP</FormLabel><input value={clientForm.cep} onChange={e => setClientForm({...clientForm, cep: e.target.value})} className={inputClass} /></div>
                            <div className="col-span-2 md:col-span-3"><FormLabel>Logradouro</FormLabel><input value={clientForm.address} onChange={e => setClientForm({...clientForm, address: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<BoltIcon />} title="Projeto" color="bg-amber-600" />
                        <div className="grid grid-cols-2 gap-4">
                            <div><FormLabel>Qtd Placas</FormLabel><input type="number" value={clientForm.plates_count} onChange={e => setClientForm({...clientForm, plates_count: parseInt(e.target.value)||0})} className={inputClass} /></div>
                            <div><FormLabel>Data Instalação</FormLabel><input type="date" value={clientForm.installation_end_date} onChange={e => setClientForm({...clientForm, installation_end_date: e.target.value})} className={inputClass} /></div>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsClientModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" disabled={isSaving} className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-black text-xs shadow-lg">Salvar Cadastro</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isPackageModalOpen && (
                <Modal title="Planos de Lavagem" onClose={() => setIsPackageModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-3">
                            <h4 className="text-[10px] font-black text-gray-400 uppercase border-b pb-2">Ativos</h4>
                            <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
                                {packages.map(pkg => (
                                    <div key={pkg.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: pkg.color }}></div>
                                            <span className="text-xs font-black text-gray-800 dark:text-white">{pkg.name}</span>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => handleEditPackage(pkg)} className="p-1 text-gray-400 hover:text-indigo-600 transition-colors"><EditIcon className="w-4 h-4" /></button>
                                            <button onClick={() => handleDeletePackage(pkg.id)} className="p-1 text-gray-400 hover:text-red-500 transition-colors"><TrashIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <form onSubmit={handleSavePackage} className="space-y-4 bg-gray-50 dark:bg-gray-800/40 p-4 rounded-2xl border">
                            <h4 className="text-[10px] font-black text-indigo-600 uppercase">{editingPackage ? 'Editar' : 'Novo'}</h4>
                            <div><FormLabel>Nome do Plano</FormLabel><input required value={packageForm.name} onChange={e => setPackageForm({...packageForm, name: e.target.value})} className={inputClass} /></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><FormLabel>Visitas</FormLabel><input type="number" required value={packageForm.wash_qty} onChange={e => setPackageForm({...packageForm, wash_qty: parseInt(e.target.value)||1})} className={inputClass} /></div>
                                <div><FormLabel>Preço/Placa</FormLabel><input type="number" step="0.01" value={packageForm.price_per_plate} onChange={e => setPackageForm({...packageForm, price_per_plate: parseFloat(e.target.value)||0})} className={inputClass} /></div>
                            </div>
                            <button type="submit" disabled={isSaving} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-xs">{isSaving ? 'Gravando...' : 'Salvar Plano'}</button>
                        </form>
                    </div>
                </Modal>
            )}

            {isLaunchServiceModalOpen && (
                <Modal title="Lançar Ciclo de Serviço" onClose={() => setIsLaunchServiceModalOpen(false)} maxWidth="max-w-md">
                    <form onSubmit={handleLaunchService} className="space-y-5 pt-2">
                        <div>
                            <FormLabel>Cliente</FormLabel>
                            <select required disabled={isClientLocked} value={launchServiceForm.clientId} onChange={e => setLaunchServiceForm({...launchServiceForm, clientId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <FormLabel>Plano de Lavagens</FormLabel>
                            <select required value={launchServiceForm.packageId} onChange={e => setLaunchServiceForm({...launchServiceForm, packageId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {packages.map(p => <option key={p.id} value={p.id}>{p.name} ({p.wash_qty}x)</option>)}
                            </select>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsLaunchServiceModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" disabled={isSaving} className="flex-[2] py-3 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-lg">{isSaving ? 'Processando...' : 'Confirmar Lançamento'}</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isHistoryModalOpen && selectedClientForModal && (
                <Modal title={`Histórico: ${selectedClientForModal.name}`} onClose={() => setIsHistoryModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="space-y-4 pt-1">
                        <div className="max-h-[400px] overflow-y-auto pr-2 custom-scrollbar space-y-2">
                            {records.filter(r => r.client_id === selectedClientForModal.id).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                                <div key={record.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border border-gray-100 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${record.status === 'executed' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                            {record.status === 'executed' ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                        </div>
                                        <div>
                                            <p className="text-xs font-black text-gray-800 dark:text-white">Lavagem em {new Date(record.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</p>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase">{record.status === 'executed' ? 'Concluída' : 'Agendada'}</p>
                                        </div>
                                    </div>
                                    <button onClick={async () => { if(confirm('Remover registro?')) { await dataService.delete('lavagem_records', record.id); loadData(); } }} className="p-2 text-gray-300 hover:text-red-500"><TrashIcon className="w-5 h-5" /></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </Modal>
            )}

            {isConfirmActionModalOpen && pendingAction && (
                <Modal title="Confirmar" onClose={() => setIsConfirmActionModalOpen(false)} maxWidth="max-w-sm">
                    <div className="text-center p-4 space-y-6">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-indigo-50 text-indigo-600"><CheckCircleIcon className="w-10 h-10" /></div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Marcar como concluída?</h3>
                        <div className="flex gap-4">
                            <button onClick={() => setIsConfirmActionModalOpen(false)} className="flex-1 py-3 bg-gray-100 rounded-xl font-bold text-sm">Não</button>
                            <button onClick={executePendingAction} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg">Sim, confirmar</button>
                        </div>
                    </div>
                </Modal>
            )}

            {isSuccessModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 animate-fade-in">
                    <div className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-2xl max-w-sm w-full text-center space-y-6">
                        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto animate-bounce"><CheckCircleIcon className="w-12 h-12" /></div>
                        <h3 className="text-xl font-black text-gray-800 dark:text-white">Concluído!</h3>
                        <p className="text-sm text-gray-500 font-bold">{modalMessage}</p>
                        <button onClick={() => setSuccessModalOpen(false)} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest">Entendido</button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
    SparklesIcon, PlusIcon, TrashIcon, EditIcon, 
    CalendarIcon, MapIcon, BoltIcon, CheckCircleIcon, 
    XCircleIcon, SearchIcon, ClockIcon, DollarIcon,
    ChevronDownIcon, HomeIcon, MapPinIcon, UsersIcon, ClipboardListIcon,
    ExclamationTriangleIcon, FilterIcon, ArrowLeftIcon, TrendUpIcon, StarIcon,
    DocumentReportIcon, PhoneIcon
} from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { dataService } from '../services/dataService';
import type { User, LavagemPackage, LavagemClient, LavagemRecord, FinancialCategory, LavagemContract } from '../types';

const toSentenceCase = (str: string) => {
    if (!str) return '';
    const clean = str.toLowerCase();
    return clean.charAt(0).toUpperCase() + clean.slice(1);
};

const formatCurrency = (value: number) => {
    if (value === undefined || value === null || isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const FormLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="block text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-1 ml-0.5 tracking-tight">{children}</label>
);

const SectionHeader: React.FC<{ icon: React.ReactElement<any>; title: string; color?: string; rightElement?: React.ReactNode }> = ({ icon, title, color = "bg-indigo-600", rightElement }) => {
    const isHex = color.startsWith('#');
    return (
        <div className="flex items-center justify-between mb-3 pb-1 border-b border-gray-100 dark:border-gray-700/50">
            <div className="flex items-center gap-2">
                <div 
                    className={`p-1 rounded-lg text-white ${!isHex ? color : ''}`}
                    style={isHex ? { backgroundColor: color } : {}}
                >
                    {React.cloneElement(icon, { className: "w-3.5 h-3.5" })}
                </div>
                <h4 className="text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-wider">{title}</h4>
            </div>
            {rightElement && <div>{rightElement}</div>}
        </div>
    );
};

const PRESET_COLORS = [
    { name: 'Indigo', hex: '#6366f1' },
    { name: 'Esmeralda', hex: '#10b981' },
    { name: 'Âmbar', hex: '#f59e0b' },
    { name: 'Rosa', hex: '#f43f5e' },
    { name: 'Céu', hex: '#0ea5e9' },
    { name: 'Violeta', hex: '#8b5cf6' },
    { name: 'Laranja', hex: '#f97316' },
    { name: 'Ouro', hex: '#d4af37' }
];

type PendingAction = {
    type: 'execute' | 'delete' | 'update';
    record: LavagemRecord;
    payload?: {
        date: string;
        status: 'scheduled' | 'executed' | 'cancelled';
    };
};

type Frequency = 'trimestral' | 'semestral' | 'anual' | 'manual';

export default function LavagemPage({ currentUser }: { currentUser: User }) {
    const [packages, setPackages] = useState<LavagemPackage[]>([]);
    const [clients, setClients] = useState<LavagemClient[]>([]);
    const [records, setRecords] = useState<LavagemRecord[]>([]);
    const [contracts, setContracts] = useState<LavagemContract[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingCep, setIsLoadingCep] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    const [activeTab, setActiveTab] = useState<'timeline' | 'oportunidades'>('timeline');
    const [filterStatus, setFilterStatus] = useState('Todos');
    const [usePeriodFilter, setUsePeriodFilter] = useState(false);
    const [periodStart, setPeriodStart] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]); 
    const [periodEnd, setPeriodEnd] = useState(new Date().toISOString().split('T')[0]);

    const [isClientModalOpen, setIsClientModalOpen] = useState(false);
    const [isPackageModalOpen, setIsPackageModalOpen] = useState(false);
    const [isWashModalOpen, setIsWashModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [isLaunchServiceModalOpen, setIsLaunchServiceModalOpen] = useState(false);
    const [isEditWashDateModalOpen, setIsEditWashDateModalOpen] = useState(false);
    const [isConfirmActionModalOpen, setIsConfirmActionModalOpen] = useState(false);
    const [isContractDetailModalOpen, setIsContractDetailModalOpen] = useState(false);

    const [editingClient, setEditingClient] = useState<LavagemClient | null>(null);
    const [editingPackage, setEditingPackage] = useState<LavagemPackage | null>(null);
    const [selectedClientForModal, setSelectedClientForModal] = useState<LavagemClient | null>(null);
    const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
    const [isClientLocked, setIsClientLocked] = useState(false);

    const [clientForm, setClientForm] = useState<Partial<LavagemClient>>({
        name: '', phone: '', cep: '', address: '', address_number: '', complement: '', city: '', plates_count: 0, installation_end_date: '', observations: ''
    });
    const [packageForm, setPackageForm] = useState({
        name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0
    });
    const [scheduleDates, setScheduleDates] = useState<string[]>([]);
    const [frequency, setFrequency] = useState<Frequency>('semestral');
    const [launchServiceForm, setLaunchServiceForm] = useState({ 
        clientId: '', 
        packageId: '',
        installationEndDate: new Date().toISOString().split('T')[0],
        travelCost: 0
    });
    const [editWashValue, setEditWashValue] = useState<{ date: string, status: 'scheduled' | 'executed' | 'cancelled' }>({ date: '', status: 'scheduled' });

    const lastFetchedCep = useRef('');

    const loadData = async () => {
        setIsLoading(true);
        try {
            const isAdmin = String(currentUser.profileId) === '001';
            const [pkgData, cliData, recData, contractData] = await Promise.all([
                dataService.getAll<LavagemPackage>('lavagem_packages', currentUser.id, isAdmin),
                dataService.getAll<LavagemClient>('lavagem_clients', currentUser.id, isAdmin),
                dataService.getAll<LavagemRecord>('lavagem_records', currentUser.id, isAdmin),
                dataService.getAll<LavagemContract>('lavagem_contracts', undefined, true) 
            ]);
            setPackages(pkgData.sort((a, b) => (a.wash_qty - b.wash_qty) || a.name.localeCompare(b.name)));
            setClients(cliData.sort((a,b) => a.name.localeCompare(b.name)));
            setRecords(recData);
            setContracts(contractData || []);
        } catch (e) { console.error(e); } finally { setIsLoading(false); }
    };

    useEffect(() => { loadData(); }, [currentUser.id]);

    const getClientPackageInfo = (client: LavagemClient) => {
        const pkg = packages.find(p => p.id === client.package_id);
        const clientRecords = records.filter(r => r.client_id === client.id);
        const launchDate = client.package_launch_date || '1970-01-01';
        const currentCycleRecords = clientRecords.filter(r => (r.created_at || r.date) >= launchDate);
        const executedCount = currentCycleRecords.filter(r => r.status === 'executed').length;
        const washQtyLimit = client.contract_wash_qty || pkg?.wash_qty || 0;
        const pricePerPlate = client.contract_price_per_plate || pkg?.price_per_plate || 0;
        const allScheduled = currentCycleRecords.filter(r => r.status === 'scheduled').sort((a, b) => a.date.localeCompare(b.date));
        const nextScheduled = allScheduled[0];
        const pendingToScheduleCount = Math.max(0, washQtyLimit - executedCount - allScheduled.length);

        const subtotalPlacas = pricePerPlate * (client.plates_count || 0);
        const contractTotalValue = (subtotalPlacas * washQtyLimit) + (client.travel_cost || 0);

        const totalAccumulated = contracts
            .filter(c => c.client_id === client.id)
            .reduce((acc, c) => acc + Number(c.total_value), 0);

        const lastExecutedWash = clientRecords
            .filter(r => r.status === 'executed')
            .sort((a, b) => b.date.localeCompare(a.date))[0];

        const lastEventDate = lastExecutedWash?.date || client.installation_end_date;
        let daysSinceLastEvent = 0;
        let isCriticalOpportunity = false;
        let isModerateOpportunity = false;

        if (lastEventDate) {
            const dateObj = new Date(lastEventDate);
            const today = new Date();
            const diffTime = Math.abs(today.getTime() - dateObj.getTime());
            daysSinceLastEvent = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            isModerateOpportunity = daysSinceLastEvent >= 180;
            isCriticalOpportunity = daysSinceLastEvent >= 330;
        }

        return { 
            pkg, executedCount, washQtyLimit, nextScheduled, allScheduled, 
            pendingToScheduleCount, contractTotalValue, totalAccumulated,
            daysSinceLastEvent, lastEventDate, isCriticalOpportunity, isModerateOpportunity,
            hasNeverWashed: !lastExecutedWash
        };
    };

    const visibleClientsWithInfo = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];

        return clients.map(client => ({
            client,
            info: getClientPackageInfo(client)
        })).filter(({ client, info }) => {
            if (activeTab === 'oportunidades' && client.package_id) return false;
            if (activeTab === 'timeline' && !client.package_id) return false;
            if (searchTerm && !client.name.toLowerCase().includes(searchTerm.toLowerCase()) && !(client.city || '').toLowerCase().includes(searchTerm.toLowerCase())) return false;

            if (activeTab === 'timeline') {
                const isFinished = info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0;
                const hasOverdue = info.allScheduled.some(r => r.date < todayStr);

                if (filterStatus !== 'Todos') {
                    if (filterStatus === 'Atrasados' && !hasOverdue) return false;
                    if (filterStatus === 'Ciclo Finalizado' && !isFinished) return false;
                    if (filterStatus === 'Com agendamentos' && info.allScheduled.length === 0) return false;
                    if (filterStatus === 'Sem Agendamento' && info.pendingToScheduleCount === 0) return false;
                }

                if (usePeriodFilter) {
                    const scheduledInPeriod = info.allScheduled.some(r => r.date >= periodStart && r.date <= periodEnd);
                    const executedInPeriod = records.filter(r => r.client_id === client.id).some(r => r.status === 'executed' && r.date >= periodStart && r.date <= periodEnd);
                    if (!scheduledInPeriod && !executedInPeriod) return false;
                }
            }

            if (activeTab === 'oportunidades' && filterStatus === 'Oportunidade 1 Ano') {
                const oneYearAgoStr = new Date(new Date().setFullYear(new Date().getFullYear() - 1)).toISOString().split('T')[0];
                if (!client.installation_end_date || client.installation_end_date > oneYearAgoStr) return false;
            }
            return true;
        });
    }, [clients, packages, records, contracts, activeTab, searchTerm, filterStatus, usePeriodFilter, periodStart, periodEnd]);

    const timelineGroups = useMemo(() => {
        if (activeTab !== 'timeline') return [];
        const groups: Record<string, { label: string, items: any[] }> = {
            'pending': { label: 'Ação necessária / Ciclos pendentes', items: [] }
        };
        visibleClientsWithInfo.forEach(item => {
            const nextDate = item.info.nextScheduled?.date || null;
            if (nextDate) {
                const date = new Date(nextDate);
                const monthYearKey = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
                const monthLabel = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                if (!groups[monthYearKey]) groups[monthYearKey] = { label: toSentenceCase(monthLabel), items: [] };
                groups[monthYearKey].items.push(item);
            } else {
                groups['pending'].items.push(item);
            }
        });
        return Object.keys(groups).sort((a, b) => a === 'pending' ? -1 : a.localeCompare(b)).map(key => ({ key, ...groups[key] })).filter(g => g.items.length > 0);
    }, [visibleClientsWithInfo, activeTab]);

    const handleSaveClient = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemClient = {
                id: editingClient ? editingClient.id : `wash-cli-${Date.now()}`,
                owner_id: currentUser.id,
                name: clientForm.name!,
                phone: clientForm.phone,
                cep: clientForm.cep!,
                address: clientForm.address!,
                address_number: clientForm.address_number!,
                complement: clientForm.complement!,
                city: clientForm.city!,
                plates_count: clientForm.plates_count!,
                observations: clientForm.observations,
                installation_end_date: clientForm.installation_end_date || undefined,
                package_id: editingClient?.package_id,
                contract_wash_qty: editingClient?.contract_wash_qty,
                contract_price_per_plate: editingClient?.contract_price_per_plate,
                package_launch_date: editingClient?.package_launch_date,
                travel_cost: editingClient?.travel_cost
            };
            await dataService.save('lavagem_clients', data);
            setIsClientModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleSavePackage = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemPackage = {
                id: editingPackage ? editingPackage.id : `wash-pkg-${Date.now()}`,
                owner_id: currentUser.id,
                name: packageForm.name,
                color: packageForm.color,
                wash_qty: packageForm.wash_qty,
                price_per_plate: packageForm.price_per_plate
            };
            await dataService.save('lavagem_packages', data);
            setEditingPackage(null);
            setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 });
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleEditPackage = (pkg: LavagemPackage) => {
        setEditingPackage(pkg);
        setPackageForm({ name: pkg.name, color: pkg.color, wash_qty: pkg.wash_qty, price_per_plate: pkg.price_per_plate });
    };

    const handleLaunchService = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!launchServiceForm.clientId || !launchServiceForm.packageId) return;
        const client = clients.find(c => c.id === launchServiceForm.clientId);
        const selectedPkg = packages.find(p => p.id === launchServiceForm.packageId);
        if (!client || !selectedPkg) return;
        setIsSaving(true);
        try {
            const launchDate = new Date();
            const platesTotal = selectedPkg.price_per_plate * (client.plates_count || 0);
            const contractTotal = (platesTotal * selectedPkg.wash_qty) + Number(launchServiceForm.travelCost || 0);
            await dataService.save('lavagem_clients', {
                ...client,
                package_id: selectedPkg.id,
                contract_price_per_plate: selectedPkg.price_per_plate,
                contract_wash_qty: selectedPkg.wash_qty,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                package_launch_date: launchDate.toISOString()
            });
            await dataService.save('lavagem_contracts', {
                id: `cont-${Date.now()}`,
                client_id: client.id,
                package_name: selectedPkg.name,
                total_value: contractTotal,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                created_at: launchDate.toISOString()
            });
            await loadData();
            setIsLaunchServiceModalOpen(false);
            alert("Plano vinculado com sucesso!");
        } finally { setIsSaving(false); }
    };

    const executePendingAction = async () => {
        if (!pendingAction) return;
        setIsSaving(true);
        try {
            if (pendingAction.type === 'execute') await dataService.save('lavagem_records', { ...pendingAction.record, status: 'executed' });
            else if (pendingAction.type === 'delete') await dataService.delete('lavagem_records', pendingAction.record.id);
            else if (pendingAction.type === 'update') await dataService.save('lavagem_records', { ...pendingAction.record, date: editWashValue.date, status: editWashValue.status });
            await loadData();
            setIsConfirmActionModalOpen(false);
            setIsEditWashDateModalOpen(false);
            setPendingAction(null);
        } finally { setIsSaving(false); }
    };

    const handleOpenLaunchModal = (clientId: string = '') => {
        const client = clients.find(c => c.id === clientId);
        setLaunchServiceForm({ 
            clientId, packageId: '', 
            installationEndDate: client?.installation_end_date || new Date().toISOString().split('T')[0],
            travelCost: 0
        });
        setIsClientLocked(!!clientId);
        setIsLaunchServiceModalOpen(true);
    };

    if (isLoading) return <div className="flex justify-center p-20"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-cyan-600"></div></div>;

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <header className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-6">
                <div className="flex items-center gap-5 flex-1">
                    <div className="p-4 bg-cyan-600 text-white rounded-2xl shadow-lg shadow-cyan-600/20"><SparklesIcon className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Gestão de Lavagens</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1">Recorrência solar inteligente</p>
                    </div>
                </div>
                <div className="flex flex-wrap justify-center gap-3">
                    <button onClick={() => { setEditingPackage(null); setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 }); setIsPackageModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Planos</button>
                    <button onClick={() => { setEditingClient(null); setClientForm({name:'', phone:'', cep:'', address:'', address_number:'', complement:'', city:'', plates_count:0, installation_end_date: '', observations: ''}); setIsClientModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Novo cliente</button>
                    <button onClick={() => handleOpenLaunchModal()} className="flex items-center gap-2 px-8 py-2.5 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-xl shadow-cyan-600/20 hover:bg-cyan-700 transition-all active:scale-95">Lançar serviço</button>
                </div>
            </header>

            <div className="flex gap-4">
                <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                    <button onClick={() => setActiveTab('timeline')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'timeline' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><CalendarIcon className="w-4 h-4" /> Timeline</button>
                    <button onClick={() => setActiveTab('oportunidades')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'oportunidades' ? 'bg-amber-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><TrendUpIcon className="w-4 h-4" /> Oportunidades {hotCount > 0 && <span className="ml-1 px-1.5 py-0.5 bg-red-500 text-white text-[8px] rounded-full">{hotCount}</span>}</button>
                </div>
            </div>

            {activeTab === 'timeline' ? (
                <div className="space-y-10">
                    {timelineGroups.map(group => (
                        <section key={group.key}>
                            <div className="flex items-center gap-4 mb-6">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white shadow-md ${group.key === 'pending' ? 'bg-slate-500' : 'bg-cyan-600'}`}>
                                    {group.key === 'pending' ? <ClockIcon className="w-6 h-6" /> : <CalendarIcon className="w-6 h-6" />}
                                </div>
                                <h3 className="text-lg font-black text-gray-800 dark:text-white">{group.label}</h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {group.items.map(({ client, info }) => {
                                    const packageColor = info.pkg?.color || '#94a3b8';
                                    const percent = info.washQtyLimit > 0 ? (info.executedCount / info.washQtyLimit) * 100 : 0;
                                    const isHighlight = group.key === 'pending' && (info.isModerateOpportunity || info.isCriticalOpportunity);

                                    return (
                                        <div 
                                            key={client.id} 
                                            className={`bg-white dark:bg-gray-800 rounded-3xl border p-5 shadow-sm hover:shadow-xl transition-all flex flex-col relative ${isHighlight ? (info.isCriticalOpportunity ? 'border-amber-400 ring-4 ring-amber-500/10' : 'border-indigo-200 ring-2 ring-indigo-500/5') : 'border-gray-100 dark:border-gray-700'}`}
                                        >
                                            {info.isCriticalOpportunity && <div className="absolute top-0 right-0 bg-amber-500 text-white px-3 py-1 rounded-bl-xl text-[8px] font-black uppercase animate-pulse">Reativação Pendente ⚠️</div>}

                                            <div className="flex justify-between items-start mb-4">
                                                <div>
                                                    <h4 className="font-black text-gray-800 dark:text-white text-base leading-tight">{client.name}</h4>
                                                    <p className="text-[10px] text-gray-400 font-bold flex items-center gap-1"><MapPinIcon className="w-3 h-3" /> {client.city || 'S/ Local'}</p>
                                                </div>
                                                <button onClick={() => { setEditingClient(client); setClientForm({...client, installation_end_date: client.installation_end_date || ''}); setIsClientModalOpen(true); }} className="p-1.5 text-gray-300 hover:text-cyan-600"><EditIcon className="w-4 h-4" /></button>
                                            </div>

                                            {/* Termômetro de Último Serviço */}
                                            <div className="bg-gray-50 dark:bg-gray-900/40 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 mb-4">
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-[9px] font-black text-gray-400 uppercase">{info.hasNeverWashed ? 'Desde Instalação' : 'Última Lavagem Realizada'}</span>
                                                    <span className={`text-[10px] font-black ${info.isModerateOpportunity ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                </div>
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                                                    <ClockIcon className="w-3.5 h-3.5 text-gray-400" />
                                                    {info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : 'Sem registro'}
                                                </p>
                                            </div>

                                            <div className="flex-1 space-y-4">
                                                {info.allScheduled.length > 0 ? (
                                                    <div style={{ backgroundColor: packageColor }} className="rounded-2xl p-3 text-white">
                                                        <div className="flex justify-between items-center mb-2">
                                                            <p className="text-[9px] font-black opacity-80">Próximo Agendamento</p>
                                                            <span className="text-[9px] font-black bg-white/20 px-2 py-0.5 rounded-full">{info.executedCount}/{info.washQtyLimit}</span>
                                                        </div>
                                                        <div className="flex justify-between items-center bg-white/10 p-2 rounded-xl">
                                                            <span className="text-xs font-black">{new Date(info.nextScheduled.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</span>
                                                            <div className="flex gap-1">
                                                                <button onClick={() => { setPendingAction({ type: 'execute', record: info.nextScheduled }); setIsConfirmActionModalOpen(true); }} className="p-1 bg-white text-indigo-600 rounded-lg shadow-sm hover:scale-110 transition-transform"><CheckCircleIcon className="w-4 h-4" /></button>
                                                                <button onClick={() => { setPendingAction({ type: 'update', record: info.nextScheduled }); setEditWashValue({ date: info.nextScheduled.date, status: info.nextScheduled.status }); setIsEditWashDateModalOpen(true); }} className="p-1 bg-black/20 text-white rounded-lg hover:scale-110 transition-transform"><EditIcon className="w-4 h-4" /></button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ) : (
                                                    <div className={`p-4 rounded-2xl border-2 border-dashed text-center ${isHighlight ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
                                                        <p className="text-[10px] font-black text-gray-500 mb-3">{isHighlight ? 'Sugerir Novo Pacote' : 'Aguardando agendamentos'}</p>
                                                        <button 
                                                            onClick={() => handleOpenLaunchModal(client.id)} 
                                                            className={`w-full py-2.5 rounded-xl font-black text-[10px] uppercase shadow-md transition-all active:scale-95 ${isHighlight ? 'bg-amber-500 text-white hover:bg-amber-600' : 'bg-slate-500 text-white'}`}
                                                        >
                                                            {info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0 ? 'Renovar Plano' : 'Lançar Novo Ciclo'}
                                                        </button>
                                                    </div>
                                                )}

                                                <div className="space-y-1.5">
                                                    <div className="flex justify-between items-end px-1">
                                                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{info.pkg?.name || '---'}</span>
                                                        <span className="text-[10px] font-black text-indigo-600">{formatCurrency(info.contractTotalValue)}</span>
                                                    </div>
                                                    <div className="w-full h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                                        <div className="h-full transition-all duration-700 rounded-full" style={{ width: `${percent}%`, backgroundColor: isHighlight ? '#f59e0b' : packageColor }} />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex gap-2 mt-4 pt-4 border-t dark:border-gray-700">
                                                <button onClick={() => { setSelectedClientForModal(client); setIsHistoryModalOpen(true); }} className="flex-1 py-2 text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-900 transition-all flex items-center justify-center gap-1.5">
                                                    <ClipboardListIcon className="w-3 h-3" /> Histórico Completo
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </section>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {visibleClientsWithInfo.map(({ client, info }) => {
                        const oneYearAgoStr = new Date(new Date().setFullYear(new Date().getFullYear() - 1)).toISOString().split('T')[0];
                        const isHot = client.installation_end_date && client.installation_end_date <= oneYearAgoStr;

                        return (
                            <div key={client.id} className={`bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 p-5 shadow-sm hover:shadow-xl transition-all flex flex-col ${isHot ? 'border-amber-400 ring-2 ring-amber-500/5' : ''}`}>
                                <div className="flex justify-between items-start mb-4">
                                    <h4 className="font-black text-gray-800 dark:text-white leading-tight">{client.name}</h4>
                                    {isHot && <span className="bg-red-500 text-white text-[7px] font-black px-1.5 py-0.5 rounded-full uppercase tracking-widest">Hot 🔥</span>}
                                </div>
                                <p className="text-[10px] text-gray-400 font-bold mb-4">{client.city || 'S/ Local'}</p>
                                <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-xl mb-4 text-center">
                                    <span className="text-[9px] font-bold text-gray-400 block mb-1 uppercase tracking-tighter">Potencial do Sistema</span>
                                    <span className="text-xl font-black text-gray-700 dark:text-white">{client.plates_count} Placas</span>
                                    <p className="text-[9px] text-gray-400 font-medium mt-1">Instalação: {client.installation_end_date ? new Date(client.installation_end_date).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : '---'}</p>
                                </div>
                                <button onClick={() => handleOpenLaunchModal(client.id)} className="w-full py-3 bg-amber-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-amber-500/20 hover:bg-amber-600 transition-colors">Lançar Plano</button>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* MODAIS RE-ESTRUTURADOS PARA GARANTIR FUNCIONAMENTO */}
            {isClientModalOpen && (
                <Modal title={editingClient ? "Editar Cliente" : "Novo Cliente Solar"} onClose={() => setIsClientModalOpen(false)} maxWidth="max-w-2xl">
                    <form onSubmit={handleSaveClient} className="space-y-4 pt-2">
                        <SectionHeader icon={<UsersIcon />} title="Identificação" />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><FormLabel>Nome Completo</FormLabel><input required value={clientForm.name} onChange={e => setClientForm({...clientForm, name: e.target.value})} className={inputClass} /></div>
                            <div><FormLabel>WhatsApp</FormLabel><input value={clientForm.phone} onChange={e => setClientForm({...clientForm, phone: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<MapPinIcon />} title="Endereço" color="bg-teal-600" />
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="col-span-1"><FormLabel>CEP</FormLabel><input value={clientForm.cep} onChange={e => setClientForm({...clientForm, cep: e.target.value})} className={inputClass} /></div>
                            <div className="col-span-2 md:col-span-3"><FormLabel>Logradouro</FormLabel><input value={clientForm.address} onChange={e => setClientForm({...clientForm, address: e.target.value})} className={inputClass} /></div>
                        </div>
                        <SectionHeader icon={<BoltIcon />} title="Projeto" color="bg-amber-600" />
                        <div className="grid grid-cols-2 gap-4">
                            <div><FormLabel>Qtd Placas</FormLabel><input type="number" value={clientForm.plates_count} onChange={e => setClientForm({...clientForm, plates_count: parseInt(e.target.value)||0})} className={inputClass} /></div>
                            <div><FormLabel>Data Instalação</FormLabel><input type="date" value={clientForm.installation_end_date} onChange={e => setClientForm({...clientForm, installation_end_date: e.target.value})} className={inputClass} /></div>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsClientModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" disabled={isSaving} className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-black text-xs shadow-lg">{isSaving ? 'Gravando...' : 'Salvar Cadastro'}</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isPackageModalOpen && (
                <Modal title="Planos de Lavagem" onClose={() => setIsPackageModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-3">
                            <h4 className="text-[10px] font-black text-gray-400 uppercase border-b pb-2">Ativos</h4>
                            <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                                {packages.map(pkg => (
                                    <div key={pkg.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: pkg.color }}></div>
                                            <span className="text-xs font-black text-gray-800 dark:text-white">{pkg.name}</span>
                                        </div>
                                        <button onClick={() => handleEditPackage(pkg)} className="p-1 text-gray-400 hover:text-indigo-600 transition-opacity opacity-0 group-hover:opacity-100"><EditIcon className="w-4 h-4" /></button>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <form onSubmit={handleSavePackage} className="space-y-4 bg-gray-50 dark:bg-gray-800/40 p-4 rounded-2xl border">
                            <h4 className="text-[10px] font-black text-indigo-600 uppercase">{editingPackage ? 'Editar' : 'Novo'}</h4>
                            <div><FormLabel>Nome do Plano</FormLabel><input required value={packageForm.name} onChange={e => setPackageForm({...packageForm, name: e.target.value})} className={inputClass} /></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><FormLabel>Visitas</FormLabel><input type="number" required value={packageForm.wash_qty} onChange={e => setPackageForm({...packageForm, wash_qty: parseInt(e.target.value)||1})} className={inputClass} /></div>
                                <div><FormLabel>Preço/Placa</FormLabel><input type="number" step="0.01" value={packageForm.price_per_plate} onChange={e => setPackageForm({...packageForm, price_per_plate: parseFloat(e.target.value)||0})} className={inputClass} /></div>
                            </div>
                            <button type="submit" disabled={isSaving} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-xs">{isSaving ? 'Salvando...' : 'Salvar Plano'}</button>
                        </form>
                    </div>
                </Modal>
            )}

            {isLaunchServiceModalOpen && (
                <Modal title="Lançar Ciclo de Serviço" onClose={() => setIsLaunchServiceModalOpen(false)} maxWidth="max-w-md">
                    <form onSubmit={handleLaunchService} className="space-y-5 pt-2">
                        <div>
                            <FormLabel>Cliente</FormLabel>
                            <select required disabled={isClientLocked} value={launchServiceForm.clientId} onChange={e => setLaunchServiceForm({...launchServiceForm, clientId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <FormLabel>Plano de Lavagens</FormLabel>
                            <select required value={launchServiceForm.packageId} onChange={e => setLaunchServiceForm({...launchServiceForm, packageId: e.target.value})} className={inputClass}>
                                <option value="">Selecionar...</option>
                                {packages.map(p => <option key={p.id} value={p.id}>{p.name} ({p.wash_qty}x)</option>)}
                            </select>
                        </div>
                        <div className="flex gap-3 pt-4 border-t">
                            <button type="button" onClick={() => setIsLaunchServiceModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl font-bold text-xs">Cancelar</button>
                            <button type="submit" disabled={isSaving} className="flex-[2] py-3 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-lg">{isSaving ? 'Gravando...' : 'Confirmar Lançamento'}</button>
                        </div>
                    </form>
                </Modal>
            )}

            {isHistoryModalOpen && selectedClientForModal && (
                <Modal title={`Histórico: ${selectedClientForModal.name}`} onClose={() => setIsHistoryModalOpen(false)} maxWidth="max-w-2xl">
                    <div className="max-h-[400px] overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                        {records.filter(r => r.client_id === selectedClientForModal.id).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                            <div key={record.id} className="p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className={`p-2 rounded-lg ${record.status === 'executed' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {record.status === 'executed' ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                    </div>
                                    <span className="text-xs font-bold text-gray-800 dark:text-white">Lavagem em {new Date(record.date).toLocaleDateString('pt-BR', {timeZone:'UTC'})}</span>
                                </div>
                                <button onClick={async () => { if(confirm('Remover registro?')) { await dataService.delete('lavagem_records', record.id); loadData(); } }} className="p-1.5 text-gray-300 hover:text-red-600"><TrashIcon className="w-4 h-4" /></button>
                            </div>
                        ))}
                    </div>
                </Modal>
            )}

            {isConfirmActionModalOpen && pendingAction && (
                <Modal title="Confirmar" onClose={() => setIsConfirmActionModalOpen(false)} maxWidth="max-w-sm">
                    <div className="text-center p-4 space-y-6">
                        <CheckCircleIcon className="w-12 h-12 text-green-500 mx-auto" />
                        <p className="font-bold text-gray-800 dark:text-white">Deseja marcar esta lavagem como concluída?</p>
                        <div className="flex gap-4">
                            <button onClick={() => setIsConfirmActionModalOpen(false)} className="flex-1 py-2 bg-gray-100 rounded-xl font-bold text-sm">Não</button>
                            <button onClick={executePendingAction} className="flex-1 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm">Sim, confirmar</button>
                        </div>
                    </div>
                </Modal>
            )}

            {isEditWashDateModalOpen && pendingAction && (
                <Modal title="Alterar Data" onClose={() => setIsEditWashDateModalOpen(false)} maxWidth="max-w-sm">
                    <div className="space-y-4 pt-2">
                        <input type="date" value={editWashValue.date} onChange={e => setEditWashValue({...editWashValue, date: e.target.value})} className={inputClass} />
                        <button onClick={executePendingAction} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold text-xs">Salvar Alteração</button>
                    </div>
                </Modal>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
    SparklesIcon, PlusIcon, TrashIcon, EditIcon, 
    CalendarIcon, MapIcon, BoltIcon, CheckCircleIcon, 
    XCircleIcon, SearchIcon, ClockIcon, DollarIcon,
    ChevronDownIcon, HomeIcon, MapPinIcon, UsersIcon, ClipboardListIcon,
    ExclamationTriangleIcon, FilterIcon, ArrowLeftIcon, TrendUpIcon, StarIcon,
    DocumentReportIcon, PhoneIcon
} from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { dataService } from '../services/dataService';
import type { User, LavagemPackage, LavagemClient, LavagemRecord, FinancialCategory, LavagemContract } from '../types';

const toSentenceCase = (str: string) => {
    if (!str) return '';
    const clean = str.toLowerCase();
    return clean.charAt(0).toUpperCase() + clean.slice(1);
};

const formatCurrency = (value: number) => {
    if (value === undefined || value === null || isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const FormLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="block text-[11px] font-bold text-gray-500 dark:text-gray-400 mb-1 ml-0.5 tracking-tight">{children}</label>
);

const SectionHeader: React.FC<{ icon: React.ReactElement<any>; title: string; color?: string; rightElement?: React.ReactNode }> = ({ icon, title, color = "bg-indigo-600", rightElement }) => {
    const isHex = color.startsWith('#');
    return (
        <div className="flex items-center justify-between mb-3 pb-1 border-b border-gray-100 dark:border-gray-700/50">
            <div className="flex items-center gap-2">
                <div 
                    className={`p-1 rounded-lg text-white ${!isHex ? color : ''}`}
                    style={isHex ? { backgroundColor: color } : {}}
                >
                    {React.cloneElement(icon, { className: "w-3.5 h-3.5" })}
                </div>
                <h4 className="text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-wider">{title}</h4>
            </div>
            {rightElement && <div>{rightElement}</div>}
        </div>
    );
};

const PRESET_COLORS = [
    { name: 'Indigo', hex: '#6366f1' },
    { name: 'Esmeralda', hex: '#10b981' },
    { name: 'Âmbar', hex: '#f59e0b' },
    { name: 'Rosa', hex: '#f43f5e' },
    { name: 'Céu', hex: '#0ea5e9' },
    { name: 'Violeta', hex: '#8b5cf6' },
    { name: 'Laranja', hex: '#f97316' },
    { name: 'Ouro', hex: '#d4af37' }
];

type PendingAction = {
    type: 'execute' | 'delete' | 'update';
    record: LavagemRecord;
    payload?: {
        date: string;
        status: 'scheduled' | 'executed' | 'cancelled';
    };
};

type Frequency = 'trimestral' | 'semestral' | 'anual' | 'manual';

export default function LavagemPage({ currentUser }: { currentUser: User }) {
    // FIX: Defined missing inputClass constant for consistent styling
    const inputClass = "w-full rounded-xl border-transparent bg-gray-50 dark:bg-gray-700/50 p-2.5 text-xs font-bold text-gray-800 dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10 shadow-sm transition-all appearance-none";

    const [packages, setPackages] = useState<LavagemPackage[]>([]);
    const [clients, setClients] = useState<LavagemClient[]>([]);
    const [records, setRecords] = useState<LavagemRecord[]>([]);
    const [contracts, setContracts] = useState<LavagemContract[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingCep, setIsLoadingCep] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    const [activeTab, setActiveTab] = useState<'timeline' | 'oportunidades'>('timeline');
    const [filterStatus, setFilterStatus] = useState('Todos');
    const [usePeriodFilter, setUsePeriodFilter] = useState(false);
    const [periodStart, setPeriodStart] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]); 
    const [periodEnd, setPeriodEnd] = useState(new Date().toISOString().split('T')[0]);

    const [isClientModalOpen, setIsClientModalOpen] = useState(false);
    const [isPackageModalOpen, setIsPackageModalOpen] = useState(false);
    const [isWashModalOpen, setIsWashModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [isLaunchServiceModalOpen, setIsLaunchServiceModalOpen] = useState(false);
    const [isEditWashDateModalOpen, setIsEditWashDateModalOpen] = useState(false);
    const [isConfirmActionModalOpen, setIsConfirmActionModalOpen] = useState(false);
    const [isContractDetailModalOpen, setIsContractDetailModalOpen] = useState(false);

    const [editingClient, setEditingClient] = useState<LavagemClient | null>(null);
    const [editingPackage, setEditingPackage] = useState<LavagemPackage | null>(null);
    const [selectedClientForModal, setSelectedClientForModal] = useState<LavagemClient | null>(null);
    const [pendingAction, setPendingAction] = useState<PendingAction | null>(null);
    const [isClientLocked, setIsClientLocked] = useState(false);

    const [clientForm, setClientForm] = useState<Partial<LavagemClient>>({
        name: '', phone: '', cep: '', address: '', address_number: '', complement: '', city: '', plates_count: 0, installation_end_date: '', observations: ''
    });
    const [packageForm, setPackageForm] = useState({
        name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0
    });
    const [scheduleDates, setScheduleDates] = useState<string[]>([]);
    const [frequency, setFrequency] = useState<Frequency>('semestral');
    const [launchServiceForm, setLaunchServiceForm] = useState({ 
        clientId: '', 
        packageId: '',
        installationEndDate: new Date().toISOString().split('T')[0],
        travelCost: 0
    });
    const [editWashValue, setEditWashValue] = useState<{ date: string, status: 'scheduled' | 'executed' | 'cancelled' }>({ date: '', status: 'scheduled' });

    const lastFetchedCep = useRef('');

    // FIX: Added missing hotCount calculation to avoid name error
    const hotCount = useMemo(() => {
        const oneYearAgoStr = new Date(new Date().setFullYear(new Date().getFullYear() - 1)).toISOString().split('T')[0];
        return clients.filter(c => !c.package_id && c.installation_end_date && c.installation_end_date <= oneYearAgoStr).length;
    }, [clients]);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const isAdmin = String(currentUser.profileId) === '001';
            const [pkgData, cliData, recData, contractData] = await Promise.all([
                dataService.getAll<LavagemPackage>('lavagem_packages', currentUser.id, isAdmin),
                dataService.getAll<LavagemClient>('lavagem_clients', currentUser.id, isAdmin),
                dataService.getAll<LavagemRecord>('lavagem_records', currentUser.id, isAdmin),
                dataService.getAll<LavagemContract>('lavagem_contracts', undefined, true) 
            ]);
            setPackages(pkgData.sort((a, b) => (a.wash_qty - b.wash_qty) || a.name.localeCompare(b.name)));
            setClients(cliData.sort((a,b) => a.name.localeCompare(b.name)));
            setRecords(recData);
            setContracts(contractData || []);
        } catch (e) { console.error(e); } finally { setIsLoading(false); }
    };

    useEffect(() => { loadData(); }, [currentUser.id]);

    const getClientPackageInfo = (client: LavagemClient) => {
        const pkg = packages.find(p => p.id === client.package_id);
        const clientRecords = records.filter(r => r.client_id === client.id);
        const launchDate = client.package_launch_date || '1970-01-01';
        const currentCycleRecords = clientRecords.filter(r => (r.created_at || r.date) >= launchDate);
        const executedCount = currentCycleRecords.filter(r => r.status === 'executed').length;
        const washQtyLimit = client.contract_wash_qty || pkg?.wash_qty || 0;
        const pricePerPlate = client.contract_price_per_plate || pkg?.price_per_plate || 0;
        const allScheduled = currentCycleRecords.filter(r => r.status === 'scheduled').sort((a, b) => a.date.localeCompare(b.date));
        const nextScheduled = allScheduled[0];
        const pendingToScheduleCount = Math.max(0, washQtyLimit - executedCount - allScheduled.length);

        const subtotalPlacas = pricePerPlate * (client.plates_count || 0);
        const contractTotalValue = (subtotalPlacas * washQtyLimit) + (client.travel_cost || 0);

        const totalAccumulated = contracts
            .filter(c => c.client_id === client.id)
            .reduce((acc, c) => acc + Number(c.total_value), 0);

        const lastExecutedWash = clientRecords
            .filter(r => r.status === 'executed')
            .sort((a, b) => b.date.localeCompare(a.date))[0];

        const lastEventDate = lastExecutedWash?.date || client.installation_end_date;
        let daysSinceLastEvent = 0;
        let isCriticalOpportunity = false;
        let isModerateOpportunity = false;

        if (lastEventDate) {
            const dateObj = new Date(lastEventDate);
            const today = new Date();
            const diffTime = Math.abs(today.getTime() - dateObj.getTime());
            daysSinceLastEvent = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            isModerateOpportunity = daysSinceLastEvent >= 180;
            isCriticalOpportunity = daysSinceLastEvent >= 330;
        }

        return { 
            pkg, executedCount, washQtyLimit, nextScheduled, allScheduled, 
            pendingToScheduleCount, contractTotalValue, totalAccumulated,
            daysSinceLastEvent, lastEventDate, isCriticalOpportunity, isModerateOpportunity,
            hasNeverWashed: !lastExecutedWash
        };
    };

    const visibleClientsWithInfo = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];

        return clients.map(client => ({
            client,
            info: getClientPackageInfo(client)
        })).filter(({ client, info }) => {
            if (activeTab === 'oportunidades' && client.package_id) return false;
            if (activeTab === 'timeline' && !client.package_id) return false;
            if (searchTerm && !client.name.toLowerCase().includes(searchTerm.toLowerCase()) && !(client.city || '').toLowerCase().includes(searchTerm.toLowerCase())) return false;

            if (activeTab === 'timeline') {
                const isFinished = info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0;
                const hasOverdue = info.allScheduled.some(r => r.date < todayStr);

                if (filterStatus !== 'Todos') {
                    if (filterStatus === 'Atrasados' && !hasOverdue) return false;
                    if (filterStatus === 'Ciclo Finalizado' && !isFinished) return false;
                    if (filterStatus === 'Com agendamentos' && info.allScheduled.length === 0) return false;
                    if (filterStatus === 'Sem Agendamento' && info.pendingToScheduleCount === 0) return false;
                }

                if (usePeriodFilter) {
                    const scheduledInPeriod = info.allScheduled.some(r => r.date >= periodStart && r.date <= periodEnd);
                    const executedInPeriod = records.filter(r => r.client_id === client.id).some(r => r.status === 'executed' && r.date >= periodStart && r.date <= periodEnd);
                    if (!scheduledInPeriod && !executedInPeriod) return false;
                }
            }

            if (activeTab === 'oportunidades' && filterStatus === 'Oportunidade 1 Ano') {
                const oneYearAgoStr = new Date(new Date().setFullYear(new Date().getFullYear() - 1)).toISOString().split('T')[0];
                if (!client.installation_end_date || client.installation_end_date > oneYearAgoStr) return false;
            }
            return true;
        });
    }, [clients, packages, records, contracts, activeTab, searchTerm, filterStatus, usePeriodFilter, periodStart, periodEnd]);

    const timelineGroups = useMemo(() => {
        if (activeTab !== 'timeline') return [];
        const groups: Record<string, { label: string, items: any[] }> = {
            'pending': { label: 'Ação necessária / Ciclos pendentes', items: [] }
        };
        visibleClientsWithInfo.forEach(item => {
            const nextDate = item.info.nextScheduled?.date || null;
            if (nextDate) {
                const date = new Date(nextDate);
                const monthYearKey = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
                const monthLabel = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                if (!groups[monthYearKey]) groups[monthYearKey] = { label: toSentenceCase(monthLabel), items: [] };
                groups[monthYearKey].items.push(item);
            } else {
                groups['pending'].items.push(item);
            }
        });
        return Object.keys(groups).sort((a, b) => a === 'pending' ? -1 : a.localeCompare(b)).map(key => ({ key, ...groups[key] })).filter(g => g.items.length > 0);
    }, [visibleClientsWithInfo, activeTab]);

    const handleSaveClient = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemClient = {
                id: editingClient ? editingClient.id : `wash-cli-${Date.now()}`,
                owner_id: currentUser.id,
                name: clientForm.name!,
                phone: clientForm.phone,
                cep: clientForm.cep!,
                address: clientForm.address!,
                address_number: clientForm.address_number!,
                complement: clientForm.complement!,
                city: clientForm.city!,
                plates_count: clientForm.plates_count!,
                observations: clientForm.observations,
                installation_end_date: clientForm.installation_end_date || undefined,
                package_id: editingClient?.package_id,
                contract_wash_qty: editingClient?.contract_wash_qty,
                contract_price_per_plate: editingClient?.contract_price_per_plate,
                package_launch_date: editingClient?.package_launch_date,
                travel_cost: editingClient?.travel_cost
            };
            await dataService.save('lavagem_clients', data);
            setIsClientModalOpen(false);
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleSavePackage = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const data: LavagemPackage = {
                id: editingPackage ? editingPackage.id : `wash-pkg-${Date.now()}`,
                owner_id: currentUser.id,
                name: packageForm.name,
                color: packageForm.color,
                wash_qty: packageForm.wash_qty,
                price_per_plate: packageForm.price_per_plate
            };
            await dataService.save('lavagem_packages', data);
            setEditingPackage(null);
            setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 });
            await loadData();
        } finally { setIsSaving(false); }
    };

    const handleEditPackage = (pkg: LavagemPackage) => {
        setEditingPackage(pkg);
        setPackageForm({ name: pkg.name, color: pkg.color, wash_qty: pkg.wash_qty, price_per_plate: pkg.price_per_plate });
    };

    const handleLaunchService = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!launchServiceForm.clientId || !launchServiceForm.packageId) return;
        const client = clients.find(c => c.id === launchServiceForm.clientId);
        const selectedPkg = packages.find(p => p.id === launchServiceForm.packageId);
        if (!client || !selectedPkg) return;
        setIsSaving(true);
        try {
            const launchDate = new Date();
            const platesTotal = selectedPkg.price_per_plate * (client.plates_count || 0);
            const contractTotal = (platesTotal * selectedPkg.wash_qty) + Number(launchServiceForm.travelCost || 0);
            await dataService.save('lavagem_clients', {
                ...client,
                package_id: selectedPkg.id,
                contract_price_per_plate: selectedPkg.price_per_plate,
                contract_wash_qty: selectedPkg.wash_qty,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                package_launch_date: launchDate.toISOString()
            });
            await dataService.save('lavagem_contracts', {
                id: `cont-${Date.now()}`,
                client_id: client.id,
                package_name: selectedPkg.name,
                total_value: contractTotal,
                travel_cost: Number(launchServiceForm.travelCost || 0),
                created_at: launchDate.toISOString()
            });
            await loadData();
            setIsLaunchServiceModalOpen(false);
            alert("Plano vinculado com sucesso!");
        } finally { setIsSaving(false); }
    };

    const executePendingAction = async () => {
        if (!pendingAction) return;
        setIsSaving(true);
        try {
            if (pendingAction.type === 'execute') await dataService.save('lavagem_records', { ...pendingAction.record, status: 'executed' });
            else if (pendingAction.type === 'delete') await dataService.delete('lavagem_records', pendingAction.record.id);
            else if (pendingAction.type === 'update') await dataService.save('lavagem_records', { ...pendingAction.record, date: editWashValue.date, status: editWashValue.status });
            await loadData();
            setIsConfirmActionModalOpen(false);
            setIsEditWashDateModalOpen(false);
            setPendingAction(null);
        } finally { setIsSaving(false); }
    };

    const handleOpenLaunchModal = (clientId: string = '') => {
        const client = clients.find(c => c.id === clientId);
        setLaunchServiceForm({ 
            clientId, packageId: '', 
            installationEndDate: client?.installation_end_date || new Date().toISOString().split('T')[0],
            travelCost: 0
        });
        setIsClientLocked(!!clientId);
        setIsLaunchServiceModalOpen(true);
    };

    if (isLoading) return <div className="flex justify-center p-20"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-cyan-600"></div></div>;

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <header className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-6">
                <div className="flex items-center gap-5 flex-1">
                    <div className="p-4 bg-cyan-600 text-white rounded-2xl shadow-lg shadow-cyan-600/20"><SparklesIcon className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Gestão de Lavagens</h2>
                        <p className="text-xs text-gray-500 font-bold mt-1">Recorrência solar inteligente</p>
                    </div>
                </div>
                <div className="flex flex-wrap justify-center gap-3">
                    <button onClick={() => { setEditingPackage(null); setPackageForm({ name: '', color: PRESET_COLORS[0].hex, wash_qty: 4, price_per_plate: 0 }); setIsPackageModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Planos</button>
                    <button onClick={() => { setEditingClient(null); setClientForm({name:'', phone:'', cep:'', address:'', address_number:'', complement:'', city:'', plates_count:0, installation_end_date: '', observations: ''}); setIsClientModalOpen(true); }} className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-600 rounded-xl font-black text-xs hover:bg-gray-100 transition-all tracking-tight">Novo cliente</button>
                    <button onClick={() => handleOpenLaunchModal()} className="flex items-center gap-2 px-8 py-2.5 bg-cyan-600 text-white rounded-xl font-black text-xs shadow-xl shadow-cyan-600/20 hover:bg-cyan-700 transition-all active:scale-95">Lançar serviço</button>
                </div>
            </header>

            <div className="flex gap-4">
                <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                    <button onClick={() => setActiveTab('timeline')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'timeline' ? 'bg-cyan-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><CalendarIcon className="w-4 h-4" /> Timeline</button>
                    <button onClick={() => setActiveTab('oportunidades')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeTab === 'oportunidades' ? 'bg-amber-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}><TrendUpIcon className="w-4 h-4" /> Oportunidades {hotCount > 0 && <span className="ml-1 px-1.5 py-0.5 bg-red-500 text-white text-[8px] rounded-full">{hotCount}</span>}</button>
                </div>
            </div>

            {activeTab === 'timeline' ? (
                <div className="space-y-10">
                    {timelineGroups.map(group => (
                        <section key={group.key}>
                            <div className="flex items-center gap-4 mb-6">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white shadow-md ${group.key === 'pending' ? 'bg-slate-500' : 'bg-cyan-600'}`}>
                                    {group.key === 'pending' ? <ClockIcon className="w-6 h-6" /> : <CalendarIcon className="w-6 h-6" />}
                                </div>
                                <h3 className="text-lg font-black text-gray-800 dark:text-white">{group.label}</h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {group.items.map(({ client, info }) => {
                                    const packageColor = info.pkg?.color || '#94a3b8';
                                    const percent = info.washQtyLimit > 0 ? (info.executedCount / info.washQtyLimit) * 100 : 0;
                                    const isHighlight = group.key === 'pending' && (info.isModerateOpportunity || info.isCriticalOpportunity);

                                    return (
                                        <div 
                                            key={client.id} 
                                            className={`bg-white dark:bg-gray-800 rounded-3xl border p-5 shadow-sm hover:shadow-xl transition-all flex flex-col relative ${isHighlight ? (info.isCriticalOpportunity ? 'border-amber-400 ring-4 ring-amber-500/10' : 'border-indigo-200 ring-2 ring-indigo-500/5') : 'border-gray-100 dark:border-gray-700'}`}
                                        >
                                            {info.isCriticalOpportunity && <div className="absolute top-0 right-0 bg-amber-500 text-white px-3 py-1 rounded-bl-xl text-[8px] font-black uppercase animate-pulse">Reativação Pendente ⚠️</div>}

                                            <div className="flex justify-between items-start mb-4">
                                                <div>
                                                    <h4 className="font-black text-gray-800 dark:text-white text-base leading-tight">{client.name}</h4>
                                                    <p className="text-[10px] text-gray-400 font-bold flex items-center gap-1"><MapPinIcon className="w-3 h-3" /> {client.city || 'S/ Local'}</p>
                                                </div>
                                                <button onClick={() => { setEditingClient(client); setClientForm({...client, installation_end_date: client.installation_end_date || ''}); setIsClientModalOpen(true); }} className="p-1.5 text-gray-300 hover:text-cyan-600"><EditIcon className="w-4 h-4" /></button>
                                            </div>

                                            {/* Termômetro de Último Serviço */}
                                            <div className="bg-gray-50 dark:bg-gray-900/40 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 mb-4">
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="text-[9px] font-black text-gray-400 uppercase">{info.hasNeverWashed ? 'Desde Instalação' : 'Última Lavagem Realizada'}</span>
                                                    <span className={`text-[10px] font-black ${info.isModerateOpportunity ? 'text-amber-600' : 'text-indigo-600'}`}>Há {info.daysSinceLastEvent} dias</span>
                                                </div>
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                                                    <ClockIcon className="w-3.5 h-3.5 text-gray-400" />
                                                    {info.lastEventDate ? new Date(info.lastEventDate).toLocaleDateString('pt-BR', {timeZone:'UTC'}) : 'Sem registro'}
                                                </p>
                                            </div>

                                            <div className="flex-1 space-y-4">
                                                {info.allScheduled.length > 0 ? (
                                                    <div style={{ backgroundColor: packageColor }} className="rounded-2xl p-3 text-white">
                                                        <div className="flex justify-between items-center mb-2">
                                                            <p className="text-[9px] font-black opacity-80">Próximo Agendamento</p>
                                                            <span className="text-[9px] font-black bg-white/20 px-2 py-0.5 rounded-full">{info.executedCount}/{info.washQtyLimit}</span>
                                                        </div>
                                                        <div className="flex justify-between items-center bg-white/10 p-2 rounded-xl">
                                                            <span className="text-xs font-black">{new Date(info.nextScheduled.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</span>
                                                            <div className="flex gap-1">
                                                                <button onClick={() => { setPendingAction({ type: 'execute', record: info.nextScheduled }); setIsConfirmActionModalOpen(true); }} className="p-1 bg-white text-indigo-600 rounded-lg shadow-sm hover:scale-110 transition-transform"><CheckCircleIcon className="w-4 h-4" /></button>
                                                                <button onClick={() => { setPendingAction({ type: 'update', record: info.nextScheduled }); setEditWashValue({ date: info.nextScheduled.date, status: info.nextScheduled.status }); setIsEditWashDateModalOpen(true); }} className="p-1 bg-black/20 text-white rounded-lg hover:scale-110 transition-transform"><EditIcon className="w-4 h-4" /></button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ) : (
                                                    <div className={`p-4 rounded-2xl border-2 border-dashed text-center ${isHighlight ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
                                                        <p className="text-[10px] font-black text-gray-500 mb-3">{isHighlight ? 'Sugerir Novo Pacote' : 'Aguardando agendamentos'}</p>
                                                        <button 
                                                            onClick={() => handleOpenLaunchModal(client.id)} 
                                                            className={`w-full py-2.5 rounded-xl font-black text-[10px] uppercase shadow-md transition-all active:scale-95 ${isHighlight ? 'bg-amber-500 text-white hover:bg-amber-600' : 'bg-slate-500 text-white'}`}
                                                        >
                                                            {info.executedCount >= info.washQtyLimit && info.washQtyLimit > 0 ? 'Renovar Plano' : 'Lançar Novo Ciclo'}
                                                        </button>
                                                    </div>
                                                )}

                                                <div className="space-y-1.5">
                                                    <div className="flex justify-between items-end px-1">
                                                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{info.pkg?.name || '---'}</span>
                                                        <span className="text-[10px] font-black text-indigo-600">{formatCurrency(info.contractTotalValue)}</span>
                                                    </div>
                                                    <div className="w-full h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                                        <div className="h-full transition-all duration-700 rounded-full" style={{ width: `${percent}%`, backgroundColor: isHighlight ? '#f59e0b' : packageColor }} />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex gap-2 mt-4 pt-4 border-t dark:border-gray-700">
                                                <button onClick={() => { setSelectedClientForModal(client); setIsHistoryModalOpen(true); }} className="flex-1 py-2 text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-900 transition-all flex items-center justify-center gap-1.5">
                                                    <ClipboardListIcon className="w-3 h-3" /> Histórico Completo
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </section>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {visibleClientsWithInfo.map(({ client, info }) => {
